/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1194-12-25:0":{"b": ["Enrico VI fu incoronato re di Sicilia a Palermo; il regno passò agli Hohenstaufen", "421ad808"], "d": ["Enrico VI entrò a Palermo il 20 novembre 1194 e fu incoronato re il giorno di Natale; il giorno seguente a Jesi nacque il figlio Federico. Il Regno di Sicilia passò dalla dinastia normanna a quella degli Hohenstaufen.", "8da541e5"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1197-01-01:0":{"b": ["Le città toscane fondarono la Lega di San Ginesio; Firenze ne assunse la guida", "bfb52345"], "d": ["Nella lega delle città toscane, antimperiale e filopapale, fondata a San Ginesio nel 1197 alla morte di Enrico VI, Firenze si mise in primo piano; da allora in poi questa è la direzione della politica estera fiorentina.", "7759a0cd"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1198-01-01:0":{"b": ["Přemysl Ottocaro I fu incoronato re di Boemia (1197 sovrano, 1198 incoronazione)", "49201be5"], "d": ["Přemysl Ottocaro I, divenuto nel 1197 sovrano indiscusso di Boemia, fu incoronato re nel 1198; nel 1212 con la Bolla d'Oro di Sicilia il titolo regio divenne ereditario e furono regolati i rapporti con l'impero.", "0cf21980"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1198-05-17:0":{"b": ["Il piccolo Federico fu incoronato re di Sicilia a Palermo (poi Federico II)", "79b0af82"], "d": ["Dopo la morte di Enrico VI nel 1197, il figlio Federico, di tre anni, fu incoronato a Palermo il 17 maggio 1198; con la morte della madre Costanza, erede normanna, passò sotto la tutela di papa Innocenzo III.", "09ece983"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1199-01-01:0":{"b": ["Roman Mstislavič unì Galizia e Volinia", "edf59754"], "d": ["Roman Mstislavič, principe di Volinia, che prese Halyč con la morte nel 1199 di Volodymyr Jaroslavič, ultimo principe rostislavide di Halyč, unendo Galizia e Volinia fondò il Principato di Galizia-Volinia; la dinastia dei Romanovič governò fino al 1340.", "6e7123e0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1201-01-01:0":{"b": ["Il vescovo di Livonia Alberto fondò Riga / trasferì la sede vescovile a Riga", "8f99d26f"], "d": ["Dopo lo sbarco dei Tedeschi alla foce della Dvina nel 1158 e la missione dell'arcivescovo di Brema nel 1186, il vescovo di Livonia nel 1201 stabilì la sede a Riga; poco dopo fu fondato l'Ordine dei Fratelli della Spada (1202/1204).", "6134e663"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1202-01-01:0":{"b": ["L'Ordine dei Fratelli della Spada (Ordine di Livonia) fu riconosciuto dal papato", "f53f7643"], "d": ["Papa Innocenzo III riconobbe l'Ordine dei Fratelli della Spada nel 1202 o 1204; la sede dell'ordine era Wenden (Cēsis). L'ordine aprì un periodo di guerra ininterrotta contro Russi e Lituani.", "9a812c20"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1204-01-01:0":{"b": ["Partitio Romaniae: i Latini si spartirono i territori bizantini", "8f498e2a"], "d": ["Dopo la presa di Costantinopoli da parte della Quarta crociata (1204), Veneziani e crociati stipularono la Partitio Romaniae per spartirsi il bottino e i territori bizantini. Il DBI di Treccani sottolinea che questi accordi regolavano aree appartenenti non al Comune di Venezia ma al doge e ai suoi uomini, e che il comune fu sistematicamente escluso dai progetti di spartizione.", "75d36572"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1205-01-01:0":{"b": ["Ragusa (Dubrovnik), dopo il breve governo del conte locale Damiano Giuda, passò a Venezia", "1533457b"], "d": ["Ragusa, oscillante tra il Regno di Sicilia (1187) e Bisanzio (1192), nel 1205, dopo il breve dominio del conte locale Damiano Giuda, si diede a Venezia; il dominio veneziano durò circa 150 anni.", "964f2c7a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1205-01-01:1":{"b": ["Il doge Enrico Dandolo morì durante una ritirata ordinata", "e5a66067"], "d": ["Enrico Dandolo, capo veneziano della Quarta crociata, morì durante una ritirata tra maggio e giugno 1205 e fu sepolto a Santa Sofia.", "c1c02f08"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1209-01-01:0":{"b": ["I Veneziani presero (di nuovo) Modone, la ripopolarono e ne rafforzarono la difesa", "4e7f4797"], "d": ["I Veneziani nel 1209 ripresero Modone; questa e la vicina Corone (Coron) divennero punto di osservazione e stazione di rifornimento a metà della rotta Venezia-Levante.", "7098530d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1217-06-01:0":{"b": ["Haakon IV fu eletto re di Norvegia a 13 anni", "8303b789"], "d": ["Il partito dei Birkebeiner nel 1217 mise sul trono il figlio e omonimo di Haakon III; Haakon IV regnò fino al 1263 e portò l'età dell'oro della Norvegia.", "727e8c33"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1219-01-01:0":{"b": ["Valdemaro II condusse una crociata in Estonia e fondò Tallinn (Lyndanisse)", "e4c18608"], "d": ["Valdemaro II nel 1219, nel quadro della crociata verso il Baltico orientale, occupò l'Estonia settentrionale e fece costruire una fortezza a Tallinn; la città divenne sede vescovile. Secondo la narrazione tradizionale il Dannebrog scese dal cielo in questa battaglia (15 giugno 1219, Lyndanisse).", "8df3b0b9"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1222-01-01:0":{"b": ["Bolla d'Oro (Aranybulla): Andrea II riconobbe ai nobili il diritto di resistere ad atti illegali del re", "990bcd41"], "d": ["Nel 1222 il re Andrea II emanò il decreto con sigillo d'oro (Aranybulla) che riconosceva ai nobili (nobiles) il diritto di opporsi ai comportamenti del re contrari alle leggi; è una pietra miliare del rafforzamento dell'oligarchia feudale.", "07b4c047"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1224-01-01:0":{"b": ["Federico II fondò a Napoli un'università (studium) per i propri sudditi", "61741d0f"], "d": ["Federico II, perché i sudditi non dovessero recarsi per studiare fuori dal regno, fondò a Napoli uno studium generale in cui si insegnava ogni scienza; doveva essere un'alternativa alle università guelfe del nord (Bologna).", "0efbf23a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1226-01-01:0":{"b": ["La seconda Lega Lombarda rinnovò a Mosio il giuramento contro Federico II", "beabd16d"], "d": ["Quando Federico II chiese ai comuni lombardi il giuramento di fedeltà, i comuni nel 1226 rinnovarono la Lega; vi aderirono Milano, Bologna, Brescia, Bergamo, Torino, Vicenza, Padova, Treviso e poi Piacenza, Verona, Faenza ecc. L'imperatore annullò i privilegi di Costanza.", "fba47ebe"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1228-01-01:0":{"b": ["Corrado, duca di Masovia, chiamò l'Ordine Teutonico al confine prussiano; donò la terra di Culm", "d9a2fb44"], "d": ["Corrado, insufficiente di fronte alle incursioni dei Prussiani, chiamò in aiuto l'Ordine Teutonico e gli diede Culm e alcune città di confine insieme ai territori che avrebbe conquistato (1228); l'intera terra di Culm fu lasciata all'ordine nel 1230. Nel 1229 iniziò la conquista della Prussia (fortezza a Thorn).", "3451ab9f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1231-01-01:0":{"b": ["Furono promulgate le Costituzioni di Melfi (Liber Augustalis)", "66a65f82"], "d": ["Federico II nel 1231 promulgò da Melfi una nuova raccolta di leggi, il Liber Augustalis; l'amministrazione del regno fu riorganizzata dalle fondamenta con questo testo.", "e39c618e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1235-04-19:0":{"b": ["Amedeo IV diede al fratello Tommaso gran parte del Piemonte come appannaggio", "fe0c2b58"], "d": ["Amedeo IV, dopo la contesa con i fratelli, il 19 aprile 1235 investì il fratello Tommaso (Tommaso II, conte di Fiandra) signore di tutto il Piemonte da Avigliana in giù; questa è la base del ramo piemontese della dinastia sabauda.", "23c46f6d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1236-01-01:0":{"b": ["Mindaugas sconfisse i cavalieri teutonici (1236)", "5199f385"], "d": ["La pressione dei cavalieri tedeschi accelerò la formazione dello Stato lituano; Treccani attribuisce a Mindaugas la vittoria del 1236, dopo la quale Mindaugas si sarebbe convertito al cristianesimo e sarebbe diventato re (1253).", "3c0a22cd"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1237-01-01:0":{"b": ["A Cortenuova Federico II sconfisse l'esercito lombardo e catturò il carroccio di Milano", "940476af"], "d": ["Federico II, che aveva occupato Vicenza, Treviso e Mantova, nel 1237 a Cortenuova sbaragliò completamente l'esercito della Lega e prese il carroccio di Milano.", "240098b2"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1237-01-01:1":{"b": ["L'Ordine dei Fratelli della Spada si unì all'Ordine Teutonico; la Livonia divenne provincia dell'ordine", "20ac369b"], "d": ["Nel 1237 l'Ordine dei Fratelli della Spada fu incorporato nell'Ordine Teutonico; la Livonia divenne una provincia con un proprio maestro, dipendente dal gran maestro. Due anni prima anche i Cavalieri di Dobrzyń si erano uniti all'ordine.", "e9e624d8"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1239-01-01:0":{"b": ["L'invasione mongola non raggiunse Novgorod, ma la città riconobbe il dominio dell'Orda d'Oro e pagò il tributo", "ce817f73"], "d": ["L'invasione tartara del 1239-40 non giunse fino a Novgorod; tuttavia la città dovette riconoscere il dominio dell'Orda d'Oro e pagare il tributo al khan. Questa relativa indipendenza le permise di svilupparsi con il commercio anseatico.", "f6bdd744"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-01-01:0":{"b": ["La flotta genovese perse la battaglia navale al largo dell'Isola del Giglio", "4d937092"], "d": ["Genova, alleata del papa e di Venezia al tempo di Federico II, nel 1241 perse la battaglia navale al largo dell'Isola del Giglio; si riprese tuttavia rapidamente e nel 1245 al Concilio di Lione (convocato dal papa genovese Innocenzo IV) fece accettare la propria volontà.", "adcb4066"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-01-01:1":{"b": ["I Mongoli distrussero Halyč; Danylo trasferì la capitale a Cholm", "429473c7"], "d": ["I Mongoli distrussero Halyč; Danilo trasferì la capitale a Cholm (giorno ignoto, vale l'anno). Encyclopedia of Ukraine («Galicia-Volhynia»): «After the Mongols razed Halych in 1241, Kholm became the new capital.»", "d436f857"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-03-28:0":{"b": ["Valdemaro II Sejr morì", "b2f435e3"], "d": ["Valdemaro II (Sejr), che aveva esteso la Danimarca nel Baltico fino all'Estonia, morì il 28 marzo 1241; con la sua morte iniziò nel paese un periodo di frammentazione.", "516198f8"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1241-04-09:0":{"b": ["Battaglia di Legnica: i Mongoli sconfissero l'esercito di Enrico II, duca di Slesia", "5ba75b97"], "d": ["Il 9 aprile 1241 a Legnica (Liegnitz) i Mongoli sconfissero l'esercito unito dei principi slesiani, incendiarono le città della Slesia e si diressero verso l'Ungheria. L'incursione mongola da est portò lo Stato polacco al punto della dissoluzione.", "360c53d6"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1248-01-01:0":{"b": ["Jarl Birger iniziò a governare di fatto la Svezia (1248-1266)", "b7d44ef8"], "d": ["Jarl Birger, considerato il più grande statista medievale svedese, dal 1248 al 1266 governò di fatto il paese e rafforzò l'autorità regia; Magnus Ladulås (1275-1290) la proseguì.", "7f65018f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1250-12-13:0":{"b": ["L'imperatore Federico II morì nel castello di Fiorentino", "32065dff"], "d": ["Federico II morì il 13 dicembre 1250 nel castello di Fiorentino in Puglia (presso Foggia) per una febbre intestinale; il trono di Sicilia andò al figlio Corrado IV, la reggenza a Manfredi.", "153ab3c0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1253-01-01:0":{"b": ["Danylo ricevette la corona dal papa e divenne re della Rus'", "604b4ddb"], "d": ["Danylo, che cercava un sostegno occidentale contro i Mongoli, riconoscendo la supremazia ecclesiastica di papa Innocenzo IV nel 1253 ricevette la corona dal papa; ma l'aiuto che si aspettava non arrivò.", "22e466fa"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1253-01-01:1":{"b": ["Mindaugas accolse il cristianesimo e fu incoronato re di Lituania", "424666af"], "d": ["Mindaugas nel 1253, convertitosi al cattolicesimo e incoronato re, proclamò la Lituania regno; i suoi seguaci tornarono al paganesimo.", "fc42f619"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1255-01-01:0":{"b": ["Per il re di Boemia Ottocaro II fu fondata una fortezza dell'Ordine Teutonico: Königsberg", "4b6bb21c"], "d": ["La città cresciuta attorno alla fortezza costruita per l'Ordine Teutonico (1255) durante la crociata del re Ottocaro II in Prussia fu chiamata Königsberg in suo onore. La città fu distrutta nel 1263 nella rivolta dei Prussiani e ricostruita nel 1286.", "7bc46742"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1257-01-01:0":{"b": ["Guglielmo Boccanegra istituì il Capitanato del Popolo", "b7753984"], "d": ["Dopo la morte di Federico II nel 1250, di fronte alle famiglie nobili vecchie e nuove (Fieschi, Grimaldi, Doria, Spinola), la borghesia nel 1257, guidata da Guglielmo Boccanegra, istituì la carica di «capitano del Popolo»; il tentativo dittatoriale di Boccanegra fu represso nel 1262.", "2eae2a56"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1258-08-11:0":{"b": ["Manfredi fu incoronato re di Sicilia a Palermo", "95db5116"], "d": ["Manfredi, diffusa la voce della morte del nipote Corradino, con il sostegno dei musulmani di Lucera riprese il regno al legato pontificio e nel 1258 fu incoronato re a Palermo.", "1047b259"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1259-01-01:0":{"b": ["Michele II, despota d'Epiro, cedette Corfù a Manfredi", "19f2de3c"], "d": ["Nel 1259 il despota d'Epiro Michele II Angelo Comneno cedette Corfù al re di Sicilia Manfredi; nel 1267 l'isola passò a Carlo d'Angiò con il Regno di Sicilia, diventando la base navale dell'influenza angioina nei Balcani.", "1fe50b1f"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1260-01-01:0":{"b": ["Battaglia di Montaperti: gli alleati ghibellini di Manfredi sconfissero i guelfi toscani; Firenze tornò ghibellina", "7ee3d67e"], "d": ["La vittoria di Montaperti del 1260 fu l'apice della fortuna di Manfredi; Firenze passò di nuovo al governo ghibellino. La sconfitta di Manfredi a Benevento (1266) e Tagliacozzo (1268) portarono il ritorno dei guelfi.", "a3001f03"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1261-01-01:0":{"b": ["Trattato di Ninfeo: Genova ottenne da Bisanzio privilegi commerciali nel Mar Nero e nel Mediterraneo orientale", "194b1f15"], "d": ["Con il trattato di Ninfeo firmato nel 1261 con l'imperatore bizantino Michele VIII, Genova ottenne ampi privilegi nel Mar Nero e nel Mediterraneo orientale; la base della colonia di Pera-Galata e della colonizzazione di Crimea (Caffa) è questo trattato.", "6deda3b0"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:0":{"b": ["Bonifacio morì senza figli; lo zio Pietro II divenne conte di Savoia", "38fe8bbd"], "d": ["Quando Bonifacio, giovane figlio di Amedeo IV, morì senza figli nel 1263, contro il testamento del padre divenne conte il fratello Pietro II («il piccolo Carlomagno») al posto di Tommaso III, figlio di Tommaso II.", "c18af671"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:1":{"b": ["A Settepozzi Genova fu sconfitta da Venezia; fu firmata la tregua di Cremona", "060e901b"], "d": ["La guerra tra Genova e Venezia, proseguita dopo Ninfeo, si concluse nel 1263 con la sconfitta di Genova a Settepozzi e con la tregua di Cremona.", "83eacbcb"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-01-01:2":{"b": ["I Prussiani si ribellarono e distrussero il primo nucleo di Königsberg", "9b09b809"], "d": ["Nel 1263 i Prussiani, sollevatisi contro i colonizzatori cristiani, distrussero il primo nucleo di Königsberg; la città fu rifondata nell'attuale sito (status di città nel 1286).", "63cc141a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1263-12-16:0":{"b": ["Haakon IV morì nelle Orcadi dopo la battaglia di Largs", "7df398fd"], "d": ["Haakon IV, che nel 1263 aveva compiuto una spedizione nelle Ebridi per consolidare le pretese norvegesi sulla Scozia, morì nelle Orcadi dopo la battaglia di Largs; il suo regno, iniziato nel 1217, ebbe fine. Il figlio Magnus Lagabøte pose fine alla guerra con la Scozia.", "a7f678c4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1266-02-26:0":{"b": ["Battaglia di Benevento: Carlo d'Angiò sconfisse e uccise Manfredi; il regno passò agli Angioini", "40101cec"], "d": ["Il 26 febbraio 1266 a Benevento Carlo, conte d'Angiò, sbaragliò l'esercito di Manfredi; Manfredi morì sul campo di battaglia. Il Regno di Sicilia passò dagli Hohenstaufen alla dinastia angioina.", "35ac3334"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1268-01-01:0":{"b": ["Pietro II morì; il fratello Filippo I divenne conte di Savoia", "26cea9a1"], "d": ["Quando Pietro II morì nel 1268 senza figli maschi, il diritto di Tommaso III fu di nuovo ignorato; divenne conte di Savoia il fratello Filippo I. Con la morte di Filippo (1285) la contea passò ad Amedeo V.", "74420d2e"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1272-01-01:0":{"b": ["Lev Danylovyč trasferì la capitale a Leopoli", "1c030990"], "d": ["Lev Danylovyč trasferì la capitale a Leopoli.", "d6c8561a"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1278-08-26:0":{"b": ["Battaglia di Marchfeld (Dürnkrut): Ottocaro II fu sconfitto e ucciso da Rodolfo d'Asburgo", "a3d38659"], "d": ["Con l'elezione di Rodolfo d'Asburgo a re dei Romani (1273) furono richiesti indietro i feudi imperiali in mano a Ottocaro, che aveva lasciato tutti i territori tranne Boemia e Moravia. Ottocaro, che nel 1278 attaccò i ducati austriaci, fu sconfitto e morì nella battaglia di Dürnkrut, nel Marchfeld.", "683f6e78"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1280-05-09:0":{"b": ["Magnus Lagabøte morì a Bergen", "1f4309b2"], "d": ["Magnus Lagabøte («il Riformatore delle leggi»), figlio di Haakon IV, morì a Bergen il 9 maggio 1280; fu sepolto nella chiesa francescana di Olavskirke.", "7c2cd8c3"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1328-08-16:0":{"b": ["A Mantova Luigi Gonzaga si ribellò alla signoria dei Bonacolsi e prese il potere; iniziò l'epoca dei Gonzaga", "1bd79932"], "d": ["Il 16 agosto 1328 Luigi Gonzaga si ribellò alla signoria dei Bonacolsi che governava Mantova e prese il governo della città. La stessa città-Stato continuò con una nuova dinastia; i Gonzaga governarono Mantova fino al 1708.", "1c4bea74"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1052-01-01:0":{"b": ["Gli Amalfitani cacciano il duca Mansone e cercano di sottrarsi alla tutela di Salerno.", "ddfbbc83"], "d": ["Gli Amalfitani cacciano il duca Mansone e cercano di sottrarsi alla tutela di Salerno.", "ddfbbc83"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1076-01-01:0":{"b": ["Sinodo di Worms: Enrico IV dichiara deposto Gregorio VII; Gregorio lo scomunica", "36e0ddb4"], "d": ["Nel gennaio 1076 il sinodo dei vescovi tedeschi riunito a Worms dichiarò deposto Gregorio; Enrico scrisse al papa che era «non papa, ma falso monaco». Enrico fu subito scomunicato; i suoi sostenitori diminuirono e i Sassoni presero le armi.", "a40f48cd"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1088-01-01:0":{"b": ["Alla morte di Guiscardo Amalfi si ribella e proclama duca Gisulfo; il governo di Gisulfo dura solo un anno.", "8f9b063e"], "d": ["Alla morte di Guiscardo Amalfi si ribella e proclama duca Gisulfo; il governo di Gisulfo dura solo un anno.", "8f9b063e"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1096-01-01:0":{"b": ["Con una nuova rivolta Marino Sebaste diventa duca.", "bd923d74"], "d": ["Con una nuova rivolta Marino Sebaste diventa duca.", "bd923d74"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1122-01-01:0":{"b": ["Concordato di Worms: si chiude la lotta per le investiture", "4b2cf229"], "d": ["Il Concordato di Worms del 1122 chiuse la controversia sulle investiture in corso da Gregorio VII.", "5a532208"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1135-01-01:0":{"b": ["La flotta pisana saccheggiò Amalfi", "357149dc"], "d": ["Nella campagna del 1135 (e 1136-37) i Pisani, venuti in aiuto a Napoli del principe di Capua Roberto contro il re di Sicilia Ruggero II, distrussero Amalfi e saccheggiarono l'isola di Ischia.", "e362cfdf"]},
"OLAYLAR_P0036:1463-01-01:0":{"b": ["Costruzione della fortezza di Kilitbahir — controllo dello Stretto dei Dardanelli", "e994202f"], "d": ["Maometto II il Conquistatore fece costruire sulla sponda della Rumelia la fortezza di Kilitbahir per controllare il passaggio marittimo dello Stretto dei Dardanelli; insieme a Kal'a-i Sultâniyye sulla sponda opposta (anatolica) formò una coppia che batteva con i cannoni il punto più stretto. Sul momento della costruzione esistono due versioni. Evliya Çelebi scrive che la fortezza fu costruita prima della conquista di Costantinopoli, nell'anno 856 (1452). Il TDV İslâm Ansiklopedisi ritiene invece che sia stata costruita dopo la conquista: lo storico coevo Tursun Bey racconta che le due fortezze furono costruite dopo la conquista di Costantinopoli, e Kritovulos riferisce che Yâkub Bey, governatore di Gallipoli e Bolayır, fu incaricato di ciò nell'anno 867 (1463) e che la costruzione fu completata nell'869 (1464-65). La fortezza fu riparata e ampliata con l'aggiunta di una torre sotto Solimano il Magnifico (iscrizione del 948/1541).", "092e4549"]},
"OLAYLAR_P0036:1566-07-25:0":{"b": ["Presa della fortezza di Yanova (Ineu) — campagna di Szigetvár", "25f2298e"], "d": ["Durante la campagna di Szigetvár di Solimano il Magnifico, il secondo visir Pertev Pascià prese la fortezza di Yanova. Gli Ottomani diedero al luogo il nome di Yanova; la fortezza divenne il centro del sancak di Yanova-Pankota e fu poi legata al beylerbeylik di Timișoara.", "636d68fa"]},
"OLAYLAR_P0036:1566-09-01:0":{"b": ["Resa della fortezza di Gyula (Göle) — campagna di Pertev Pascià alla frontiera di Timișoara", "6fb33793"], "d": ["Durante la campagna di Szigetvár di Solimano il Magnifico, Pertev Pascià fu nominato serdar per prendere Göle (Gyula), una delle fortezze al confine del vilayet di Timișoara; furono posti ai suoi ordini tutte le forze del beylerbey di Timișoara e del sancakbey di Belgrado. Partito da Costantinopoli nel maggio 1566 con giannizzeri, silahdar e artiglieri, Pertev Pascià dopo un assedio di oltre un mese prese Göle e alcune fortezze circostanti il 1° settembre 1566. Furono aumentati i timar e gli zeamet di chi si era distinto in battaglia.", "9acca3c9"]},
"OLAYLAR_P0036:1595-10-22:0":{"b": ["Occupazione di Yanova (Ineu) da parte delle truppe transilvane", "66ec4d68"], "d": ["Nella Lunga Guerra le truppe transilvane, alleate degli Asburgo, al comando di György Borbély occuparono la cittadina di Yanova e la palanca di Erdöç; la fortezza uscì dalle mani ottomane.", "b37641b9"]},
"OLAYLAR_P0036:1868-01-01:0":{"b": ["In Qatar emerge la casata Âl-i Sânî — intervento britannico e tributo al Bahrein", "1c8fd12e"], "d": ["Gli Âl-i Sânî, che nella regione riscuotevano tributi per conto dello Sceiccato del Bahrein e dell'Emirato saudita, dagli anni 1860 divennero determinanti nella politica del Qatar. Poiché le rivalità tra la famiglia saudita del Najd e la famiglia Khalifa del Bahrein resero il Qatar importante per gli Inglesi, nell'autunno 1868 il Regno Unito inviò navi in Qatar e costrinse Muhammad b. Sânî a pagare tributo agli emiri del Bahrein. Questo intervento avviò il processo che portò alla spedizione di Lahsa del 1871 del governatore di Baghdad Midhat Pascià. Con questo evento la penisola del Qatar emerse come unità distinta sotto il governo degli Âl-i Sânî (Muhammad b. Sânî).", "cbce5ac2"]},
"OLAYLAR_P0036:1884-05-01:0":{"b": ["Berber cade in mano alle forze del Mahdi — interrotta la via del Nilo", "812f6b22"], "d": ["Mentre il movimento mahdista si diffondeva in Sudan, la città di Berber, sulle rive del Nilo, e i dintorni caddero nel maggio 1884 in mano alle forze legate al Mahdi.", "092ce212"]},
"OLAYLAR_P0036:1913-07-29:0":{"b": ["Rinuncia ottomana al Qatar — Convenzione di Londra", "52e08213"], "d": ["Con la convenzione anglo-ottomana firmata a Londra il 29 luglio 1913 l'Impero ottomano rinunciò a tutte le pretese sulla penisola del Qatar; fu accettato che la penisola fosse governata dallo sceicco Câsim b. Sânî e dai suoi successori.", "e13188d5"]},
"OLAYLAR_P0037:1689-10-01:0":{"b": ["Caduta di Vidin in mano austriaca — ottobre 1689", "d987d1f9"], "d": ["Dopo la caduta di Niš il 24 settembre, il margravio di Baden Ludovico avanzò lungo il Danubio e ricevette Vidin, con le fortezze di Fethülislâm e Florentin, senza combattere. La fortezza fu ripresa meno di un anno dopo, nella controffensiva del 1690 di Köprülüzâde Fâzıl Mustafa Pascià, dall'esercito di terra di Dursun Mehmed Pascià, mutasarrıf di Karaman, e dalla flotta danubiana di Mezemorta Hüseyin Pascià.", "f87414c0"]},
"OLAYLAR_P0057B:1431-01-01:0":{"b": ["Il più antico registro di tahrir giunto fino a noi — Registro del Sancak di Arvanid", "06981f02"], "d": ["Il più antico esemplare giunto fino a noi dei censimenti di tahrir, che registravano contribuenti, famiglie, terre e prodotti, è il Registro del Sancak di Arvanid del 835 (1431). Le commissioni di censimento confrontavano i vecchi registri con la situazione sul posto, aggiungevano al registro i nuovi adulti e cancellavano i morti. Si deduce che la procedura del registro esisteva già nel XIV secolo; il sistema fu rinnovato regolarmente nella maggior parte delle province durante il XVI secolo.", "df6b854c"]},
"OLAYLAR_P0057B:1520-01-01:0":{"b": ["Morte dello storico Neşrî", "d30aaa5c"], "d": ["Lo storico Neşrî, che fu müderris a Bursa sotto Bayezid II, secondo il TDV morì probabilmente nel 926 (1520) o 927 (1521), dopo l'ascesa al trono di Solimano il Magnifico. Poiché non esisteva una storia scritta in turco, della sua Kitâb-ı Cihannümâ sono giunte fino a noi solo le sezioni sulla storia turca preislamica e sulla storia ottomana. Il TDV lo considera il primo storico ottomano che cercò di confrontare le proprie fonti e di spiegare gli eventi con un rapporto di causa ed effetto.", "eae3b6db"]},
"OLAYLAR_P0057B:1574-01-01:0":{"b": ["L'ufficio di Darüssaade ağası si separa da quello di Bâbüssaâde ağası e diventa carica autonoma", "1adb7dd9"], "d": ["Habeşî Mehmed Ağa, avvalendosi dei poteri conferitigli, fece separare l'ufficio di Dârüssaâde ağası da quello di Bâbüssaâde (Enderun) ağası e assunse il titolo di Dârüssaâde ağası. Questa carica, capo degli eunuchi dell'harem, ebbe poteri che si estendevano dal controllo delle fondazioni dei Luoghi Santi al tesoro del palazzo, agli affari di Stato. Dal XVII secolo, nella carica gli eunuchi neri (karaağalar) prevalsero sugli eunuchi bianchi (akağalar).", "6196bf6d"]},
"OLAYLAR_P0057B:1648-01-01:0":{"b": ["Evliya Çelebi registra che a İznik le officine di ceramica sono scese a nove", "93ec22f1"], "d": ["Evliya Çelebi, che vide İznik nel 1648, scrisse che nella città, il più importante centro ceramico dell'impero, il numero delle officine di ceramica era sceso a nove; l'industria ceramica della città deve aver iniziato a declinare in quel periodo. Secondo la stessa osservazione, entro le mura vi erano diciotto quartieri e 600 botteghe. Il TDV non indica una causa unica e certa del declino.", "c052c4ea"]},
"OLAYLAR_P0057B:1702-01-01:0":{"b": ["Naîmâ, come vakanüvis, presenta la sua storia ad Amcazâde Hüseyin Pascià", "efe67a72"], "d": ["Mustafa Naîmâ, scrivano di palazzo originario di Aleppo, era stato nominato vakanüvis da Amcazâde Hüseyin Pascià prima del 1114 (1702) e nello stesso anno presentò la sua opera al pascià. La diffusa opinione che sia stato il primo storiografo ufficiale dello Stato è rafforzata dal fatto che il suo successore Râşid Efendi lo menziona come vakanüvis. Il frutto di questo lavoro, la Ravzatü'l-Hüseyn, copre all'incirca gli anni 1592-1660.", "d32ee435"]},
"OLAYLAR_P0057B:1734-01-01:0":{"b": ["La Storia di Naîmâ (Ravzatü'l-Hüseyn) stampata nella tipografia di Müteferrika", "880152ff"], "d": ["Dopo la morte di Naîmâ, la Ravzatü'l-Hüseyn, nota popolarmente come Storia di Naîmâ, fu stampata nel 1147 (1734) da İbrâhim Müteferrika in due grandi volumi e 500 copie. La prefazione scritta da Müteferrika all'inizio del primo volume fu ripetuta anche nelle edizioni successive. L'opera è uno dei primi grandi libri di storia stampati in turco in tipografia.", "81dabf05"]},
"OLAYLAR_P0057B:1756-12-22:0":{"b": ["Morte dell'erede al trono, lo şehzade Mehmed — l'ipotesi di avvelenamento è discussa", "b0f6beef"], "d": ["Lo şehzade Mehmed, figlio di Ahmed III e in posizione di erede al trono, morì e la sua morte aprì la via al trono al fratello Mustafa III. Le due voci del TDV divergono su questa morte: la voce «Mustafa III» scrive che lo şehzade morì all'improvviso e in modo sospetto, probabilmente avvelenato; la voce «Osman III» scrive invece che la morte fu per malattia e considera il fatto che Köse Mustafa Pascià sia poi diventato gran visir e candidato genero una prova dell'infondatezza dell'accusa. L'atlante non sceglie tra le due opinioni.", "81f9c156"]},
"OLAYLAR_P0060:1723-01-01:0":{"b": ["I Russi sbarcano a Enzeli e si insediano a Rasht — inizio dell'occupazione del Gilan", "15f9a0f2"], "d": ["Dopo la presa di Derbent, un contingente russo di mille uomini proveniente da Astrachan sbarcò nella baia di Enzeli e si insediò a Rasht, su richiesta del governatore della città che chiedeva aiuto contro gli Afghani. Il resto del Gilan fu preso entro il maggio 1723. L'esercito ottomano entrò invece nello stesso anno in primavera nel Caucaso attraverso Tbilisi; i due imperi avanzavano nel paese safavide in crollo da due estremità diverse.", "f4cbd759"]},
"OLAYLAR_P0060:1723-09-23:0":{"b": ["Trattato di Pietroburgo — l'ambasciatore di Tahmasp cede alla Russia le province della costa del Caspio", "ace99ff0"], "d": ["In cambio dell'aiuto militare russo contro gli Afghani, l'ambasciatore di Tahmasp II cedette alla Russia Derbent e Baku con i loro dintorni e le province di Gilan, Mazandaran e Astarabad. Tahmasp non ratificò il trattato; la Russia mantenne guarnigioni a Derbent, Baku e nel Gilan, ma non inviò mai truppe a Mazandaran e Astarabad. Le clausole territoriali del trattato furono riconosciute l'anno seguente nel Trattato di Costantinopoli firmato con gli Ottomani. Salyan fu presa dall'esercito russo dopo la presa di Baku nel 1723 (Çaycıoğlu, Vakanüvis 2, p. 126); il Trattato di Pietroburgo fu firmato il 12 settembre 1723.", "391e585d"]},
"OLAYLAR_P0060:1725-01-01:0":{"b": ["Occupazione di Lahijan da parte dei Russi — punto più orientale nel Gilan", "3d874b31"], "d": ["I Russi non riuscirono mai a spingersi oltre Lahijan nel Gilan; la città fu occupata nel 1725. Mazandaran e Astarabad, cedute con il Trattato di Pietroburgo, non passarono mai di fatto in mano russa. Nello stesso anno l'esercito ottomano prese Tabriz e Ganja, completando la sua parte in Azerbaigian.", "a350db52"]},
"OLAYLAR_P0060:1732-01-01:0":{"b": ["Trattato di Rasht — la Russia restituisce alla Persia Gilan, Mazandaran e Astarabad", "5b7eba2a"], "d": ["Dopo la morte di Pietro I la Russia, che non ricavava il reddito atteso dalle province della costa del Caspio e subiva gravi perdite per malattia, si accordò con il Nâdir in ascesa, rinunciò ai suoi diritti su Mazandaran e Astarabad e accettò di evacuare Gilan e Talish; Derbent e Baku per il momento restarono in mano russa. Nello stesso inverno anche gli Ottomani, con il Trattato di Ahmed Pascià, restituivano alla Persia gran parte della Persia occidentale: il paese spartito nel 1724 veniva ripreso otto anni dopo da due parti contemporaneamente.", "fa874206"]},
"OLAYLAR_P0060:1732-09-02:0":{"b": ["Evacuazione di Gilan e Talish da parte dei Russi — Levašov passa il Kura", "9503be07"], "d": ["Alla scadenza del termine di consegna del Trattato di Rasht il corpo russo del Gilan si ritirò da Gilan e Talish e passò a nord del fiume Kura; solo nel Gilan più di mille soldati erano morti di malattia tra gennaio e marzo 1732. La presenza russa sulla costa si ridusse al nord del Kura, a Baku e a Derbent; anch'esse furono restituite con il Trattato di Ganja del 1735.", "ec20f6a3"]},
"OLAYLAR_P0063:1724-09-11:0":{"b": ["Annientamento di un battaglione russo a Salyan — le truppe di Tahmasp entrano alla foce del Kura", "f0b425c9"], "d": ["Gli ufficiali del battaglione russo stanziato alla foce del Kura dopo la presa di Baku furono uccisi durante un banchetto offerto dal vice del governatore di Salyan; il resto della truppa si ritirò a Baku e a Salyan entrò un contingente di circa quattromila uomini di Tahmasp II. I Russi poterono tornare nella regione solo alcuni anni dopo, nominando essi stessi il governatore. È uno dei rari casi in cui, durante l'occupazione, i Russi furono respinti con le armi in Persia.", "375630fa"]},
"OLAYLAR_P0063:1734-05-31:0":{"b": ["Minaccia di Nâdir all'ambasciatore russo Golicyn: se non saranno restituite le province del Caspio e Derbent, si accorderà con gli Ottomani", "f8fec4a7"], "d": ["Nâdir, che aveva sconfitto l'esercito ottomano davanti a Erevan, rifiutò l'offerta di aiuto russa e fece sapere che, se la Russia non avesse restituito subito, oltre quanto previsto dal Trattato di Rasht, le province della costa del Caspio e Derbent, avrebbe fatto una pace separata con gli Ottomani. Pietroburgo, alla vigilia di una nuova guerra ottomana, cedette per non spingere la Persia dalla parte opposta.", "89b8c85e"]},
"OLAYLAR_P0063:1734-11-09:0":{"b": ["Ordine di ritiro russo — evacuazione di tutte le posizioni da Baku, Nizovaja e dal Kura fino a Derbent", "79a068ef"], "d": ["L'ordine dell'imperatrice Anna dispose che le forze russe si ritirassero prima da Baku e dalla fortezza di Nizovaja a Derbent, e che Derbent e le province rimanenti fossero evacuate quando la stagione lo avesse permesso. La pressione di Nâdir aveva dato risultato prima del trattato.", "9ad1e7fc"]},
"OLAYLAR_P0063:1735-01-01:0":{"b": ["Invio delle forze di Crimea attraverso la Cabardia verso la Persia — protesta della Russia e pretesto di guerra", "e2356781"], "d": ["Alle forze di Crimea fu ordinato di attraversare la regione della Cabardia, nel Caucaso, per sostenere l'esercito ottomano al confine persiano. La Russia protestò contro l'ordine sostenendo che quelle terre le appartenevano. Sebbene l'ordine fosse stato ritirato, i Russi lo presero a pretesto e nella primavera del 1736 attaccarono Azov; il vero obiettivo era riprendere Azov e raggiungere il Mar Nero.", "e31f4da0"]},
"OLAYLAR_P0063:1735-05-01:0":{"b": ["Consegna di Baku alla Persia", "5c6fa266"], "d": ["In base alla clausola di evacuazione entro due mesi del Trattato di Ganja, il comandante russo de Brilly consegnò Baku a Musa Khan, venuto a riceverla.", "68a77e77"]},
"OLAYLAR_P0063:1735-05-08:0":{"b": ["Consegna di Derbent alla Persia — fine di tredici anni di occupazione russa", "ad7b20ab"], "d": ["Le chiavi di Derbent furono consegnate alla parte persiana; alcune truppe russe rimasero ancora per un po' in città. Così l'occupazione russa iniziata nel 1722 finì, senza un'unica grande battaglia, per il desiderio della Russia di mantenere Nâdir come alleato prima di una nuova guerra con gli Ottomani.", "a72d286a"]},
"OLAYLAR_P0063:1735-07-09:0":{"b": ["Consegna di Ganja a Nâdir", "1b50eb22"], "d": ["Nâdir, che aveva sconfitto l'esercito ottomano ad Arpaçay, poche settimane dopo prese Ganja, circondata da forti mura e tre fossati. La città, presa dagli Ottomani nel 1725, tornò alla Persia; il Karabakh fu lasciato alla Persia con il trattato del 1736.", "03fc4c7d"]},
"OLAYLAR_P0063:1735-08-12:0":{"b": ["Tbilisi passa alle truppe persiane", "c463de93"], "d": ["Dopo il rafforzamento di Nâdir le truppe persiane ripresero Tbilisi e nominarono Ali Mirza al governo di Kartli-Kakheti. Nâdir cambiò l'ordinamento amministrativo ottomano del luogo; governò direttamente il Kartli con un governatore persiano e nel 1744 lo diede a Teimuraz.", "3a18c7c0"]},
"OLAYLAR_P0063:1735-08-23:0":{"b": ["Demolizione della fortezza della Santa Croce — il confine russo ritirato al Terek, fondata la fortezza di Kizljar", "1bb1117b"], "d": ["Dopo i trattati di Rasht e Ganja il nuovo confine della Russia divenne il fiume Terek; fu decisa la demolizione della fortezza della Santa Croce sul Sulak e Levašov comunicò la demolizione nell'agosto 1735. Nello stesso anno Levašov scelse il sito della fortezza di Kizljar sul Terek; la presenza russa sulla costa del Daghestan, in atto dal 1722, fu così ritirata a nord del Terek.", "85373e75"]},
"OLAYLAR_P0063:1736-05-02:0":{"b": ["Decisione di guerra contro la Russia — dopo l'attacco russo ad Azov", "d19f8545"], "d": ["Quando i Russi attaccarono la fortezza di Azov nel mese di Zilkade 1148 (marzo 1736) e marciarono su Or Kapı (Perekop), il governo ottomano, nel divan riunito, istigato anche dall'ambasciatore francese Villeneuve, fu costretto a decidere la guerra contro la Russia. Il gran visir Seyyid Mehmed Pascià fu nominato seraschiere dell'esercito. La Russia, con l'accordo di Ganja del marzo 1735, si era liberata del fronte persiano e aveva rimesso all'ordine del giorno l'obiettivo di raggiungere il Mar Nero.", "a65d5ca0"]},
"OLAYLAR_P0063:1736-06-01:0":{"b": ["Consegna di Or Kapı a Münnich — l'esercito russo entra in Crimea", "af2b2613"], "d": ["Münnich giunse davanti alle linee di Or Kapı il 16 maggio (calendario giuliano) e all'alba del 20 maggio le assalì; l'esercito tartaro, sorpreso, si ritirò e la fortezza di Or si arrese il giorno dopo. Due giorni più tardi l'esercito russo marciò nell'interno della penisola; Or Kapı rimase in mano russa fino alla fine di agosto.", "3fec9485"]},
"OLAYLAR_P0063:1736-06-19:0":{"b": ["Consegna della fortezza di Kılburun a Leontiev", "a0600527"], "d": ["Mentre Münnich avanzava in Crimea, la colonna di Leontiev, da lui distaccata, si diresse a Kılburun, alla foce del Dnepr, e la fortezza si arrese. Poiché la fonte non dà il giorno in cui le forze russe lasciarono la fortezza, la mappa non mostra una finestra di occupazione.", "c1632ebd"]},
"OLAYLAR_P0063:1736-07-13:0":{"b": ["Caduta di Azov in mano russa", "004b5ef1"], "d": ["Al termine dell'attacco iniziato nel marzo 1736 la fortezza di Azov, alla foce del Don, cadde in mano russa. Nella stessa estate i Russi superarono Or Kapı ed entrarono in Crimea, presero Gözleve e Kılburun e devastarono Bahçesaray e Akmescid. Azov restò alla Russia con la pace del 1739, ma le sue fortificazioni furono demolite. Le fonti divergono sul giorno della caduta: il TDV dà questa data insieme a Gözleve, Orkapı e Kılburun; le fonti russe dicono 19 giugno (30 giugno gregoriano), un'altra fonte 1° luglio.", "fccaab17"]},
"OLAYLAR_P0063:1736-08-27:0":{"b": ["Münnich distrugge la linea di Or Kapı e si ritira dalla Crimea", "84ee7e5c"], "d": ["Münnich, tornato a Or Kapı dall'interno della Crimea, vi rimase cinque settimane. A causa della scarsità di viveri e delle malattie diffuse nell'esercito, dopo aver fatto demolire la linea fortificata di Perekop si ritirò in Ucraina; partiti i Russi, i Tatari ricostruirono la linea.", "d453b2eb"]},
"OLAYLAR_P0063:1737-07-14:0":{"b": ["L'Austria dichiara guerra agli Ottomani — secondo fronte accanto alla Russia", "c27ed99a"], "d": ["L'Austria, alleata della Russia, mentre a Nemirov erano stati decisi negoziati di pace, nel giugno 1737 attaccò il territorio ottomano su tre colonne; la dichiarazione ufficiale di guerra dell'imperatore è datata 14 luglio 1737. Seckendorf prese Niš in luglio, ma l'operazione austriaca in Bosnia fu fermata ad agosto a Banja Luka. Questo fronte si chiuse con la perdita dell'Austria nel Trattato di Belgrado del 1739.", "7d5518a3"]},
"OLAYLAR_P0063:1737-07-25:0":{"b": ["L'avanguardia di Lacy prende e incendia Karasubazar", "ee36541f"], "d": ["Lacy, entrato in Crimea attraversando il Sivaš, il 12 luglio (calendario giuliano) respinse l'attacco del khan. Due giorni dopo il generale Douglas, all'avanguardia, disperse l'accampamento tartaro davanti a Karasubazar, prese la città senza resistenza e la incendiò. Lacy iniziò a ritirarsi il giorno dopo.", "ac1fd466"]},
"OLAYLAR_P0063:1737-07-27:0":{"b": ["Caduta di Niš in mano austriaca — campagna di Serbia di Seckendorf", "084a31e8"], "d": ["Nell'estate 1737 la colonna serba dell'esercito austriaco, entrato in territorio ottomano su tre colonne, al comando del maresciallo Seckendorf scese a sud dalla valle della Morava e prese Niš. La caduta della fortezza fu l'unico grande successo austriaco della guerra; ma nell'ottobre dello stesso anno il beylerbey di Rumelia Köprülüzâde Hâfız Ahmed Pascià riprese Niš senza combattere.", "5fd4065d"]},
"OLAYLAR_P0063:1737-10-16:0":{"b": ["Niš ripresa all'Austria", "265e0917"], "d": ["Niš, presa nel Rebîülevvel 1150 (luglio 1737) dall'esercito austriaco al comando di Seckendorf, fu ripresa nell'ottobre dello stesso anno dal beylerbey di Rumelia Köprülüzâde Hâfız Ahmed Pascià. Fu, dopo Banja Luka, il secondo sviluppo che vanificò la campagna austriaca del 1737.", "2f62abcc"]},
"OLAYLAR_P0063:1738-08-17:0":{"b": ["Ada Kaleh ripresa all'Austria", "24f58282"], "d": ["L'esercito ottomano, partito in campagna nella primavera 1738, prese Mehadia e assediò Orșova e Ada Kaleh, attraversò il Danubio e compì incursioni su Timișoara. Ada Kaleh fu presa il 17 agosto 1738. Poi Yeğen Mehmed Pascià, giunto a Niš, compì incursioni su Belgrado; un anno dopo vennero la vittoria di Hisarcık e il Trattato di Belgrado.", "9b408b77"]},
"OLAYLAR_P0065:1770-08-12:0":{"b": ["I Nogai di Yedisan e Budžak passano sotto protezione russa", "54c9791c"], "d": ["Durante l'assedio di Bender il comandante russo Panin firmò un accordo con i capi delle orde nogai di Yedisan e Budžak. I Nogai dichiararono di staccarsi dall'Impero ottomano e di porsi sotto la protezione dell'imperatrice russa. Circa dodicimila Nogai emigrarono dal Budžak; le orde furono stanziate nel 1771-1772 sulla riva destra del fiume Kuban. Con il passaggio alla parte russa delle steppe a nord della Crimea fu aperta la via di terra verso la penisola.", "8e87da5e"]},
"OLAYLAR_P0065:1771-06-26:0":{"b": ["La linea di Or Kapı (Perekop) passa ai Russi", "ae464560"], "d": ["L'esercito russo al comando di Dolgorukov, con un attacco notturno, scalò con scale l'ala sinistra della linea di Or Kapı. Nello stesso momento la cavalleria di Prozorovskij, attraversando i guadi del Sivaš, giunse alle spalle della linea e disperse la cavalleria crimeo-ottomana. Il giorno dopo la guarnigione della fortezza si arrese; l'esercito russo due giorni dopo marciò nell'interno della penisola.", "7efec9b9"]},
"OLAYLAR_P0065:1771-06-29:0":{"b": ["Caduta della fortezza di Arabat; Kerč, Yenikale e Taman passano ai Russi", "7784d628"], "d": ["La colonna russa di Ščerbatov attraversò lo stretto di Henichesk su un ponte costruito con le barche portate dalla flotta di Azov e, marciando per circa cento verste lungo la lingua di Arabat, prese la fortezza di Arabat. In luglio la stessa colonna prese anche Kerč, Yenikale e Taman. Così entrambe le rive dello stretto di Kerč passarono sotto controllo russo.", "5c9efba7"]},
"OLAYLAR_P0067:1788-09-21:0":{"b": ["Battaglia di Sebeş (Karansebeş) — ritirata notturna dell'esercito austriaco", "fcc530d0"], "d": ["Le forze ottomane al comando di Kethüdâ Hasan Pascià, seraschiere di Vidin, sconfissero l'esercito di Giuseppe II dopo Mehadia anche a Sebeş (Karansebeş). Nel consiglio nella tenda del gran visir fu deciso un attacco al campo nemico; mentre di notte proseguivano i preparativi, si vide che le truppe austriache avevano abbandonato le posizioni ritirandosi nella cittadina di Sebeş. Le forze ottomane all'inseguimento le strinsero nella cittadina; nell'incendio scoppiato morirono molti soldati, i sopravvissuti si rifugiarono a Lugoj, a sette ore di distanza, e più di mille furono fatti prigionieri. Il diario di campagna dello stesso esercito austriaco registra la stessa notte come panico e fuoco amico; per un confronto dei due racconti, lettura aggiuntiva: karsi-karansebes-1788. La città non passò sotto controllo ottomano: fu presa, incendiata e abbandonata il 10 ottobre 1788 — perciò sulla mappa non si vede alcun cambiamento di confine.", "1b1d8ea5"]},
"OLAYLAR_P0068:1427-01-01:0":{"b": ["Il principe Inal unisce i Cabardi sotto un unico governo", "34f01c9e"], "d": ["Tra il ramo cabardo dei Circassi, ritiratisi a est dopo le invasioni mongolo-tatare, il principe Inal (1427-1456) riunì sotto il proprio governo gran parte della popolazione; i principi cabardi, besleney e çemguy fanno risalire a lui la propria discendenza. I bey cabardi fino alla fine del XVIII secolo ebbero influenza anche su Ceceni, Ingusci, Karačaj-Balcari e Osseti e sugli Abazi a nord del Caucaso. La data è l'inizio degli anni di regno di Inal; il giorno dell'unificazione non è noto.", "405949a2"]},
"OLAYLAR_P0068:1475-01-01:0":{"b": ["La costa circassa riconosce la sovranità ottomana", "c61a1859"], "d": ["Le colonie genovesi sulla costa del Mar Nero, tagliate fuori dal Mediterraneo dopo la conquista di Costantinopoli, per ordine di Maometto II il Conquistatore furono prese sotto amministrazione ottomana nel 1475 da Gedik Ahmed Pascià e nel 1479 da Kasım Pascià. Le comunità che vivevano sulla costa tra Taman e Soči e che le fonti ottomane chiamano «Circassi di Aşağıra» riconobbero la sovranità ottomana; da allora la costa restò per tre secoli sotto sovranità ottomana. Si tratta del riconoscimento di una sovranità: le tribù mantennero il proprio ordinamento, e i luoghi che gli Ottomani tenevano di fatto erano fortezze costiere come Anapa, Soğucak, Gelincik, Sukhumi e Poti.", "b46e4e11"]},
"OLAYLAR_P0068:1563-01-01:0":{"b": ["La prima fortezza della Russia nel Caucaso: Terek", "5dcabb8e"], "d": ["Il principe cabardo Temrük, oppresso dalle incursioni di Crimea e dalle razzie di schiavi, nel 1557 e nel 1559 inviò ambasciatori a Mosca e diede la figlia in sposa allo zar Ivan IV. I Russi, stipulato un accordo con alcuni principi cabardi, nel 1563 fondarono sul fiume Terek la loro prima fortezza nel Caucaso. Il sultano ottomano in una lettera inviata nel 1570 chiese la demolizione delle fortezze russe in Cabardia; la fortezza fu demolita nel 1574. Questa è una questione di alleanza e di fortezza, non di passaggio di territorio — perciò sulla mappa non mostra alcun cambiamento.", "f74fed71"]},
"OLAYLAR_P0068:1763-01-01:0":{"b": ["La Russia costruisce la fortezza di Mozdok in Cabardia", "630428b1"], "d": ["In Cabardia, lasciata neutrale dal Trattato di Belgrado (1739), era iniziata la lotta tra principi filo-ottomani e filo-russi. Approfittando di questa confusione, la Russia nel 1763, nonostante le proteste dell'Impero ottomano e dei principi cabardi, fece costruire sul Terek la fortezza di Mozdok. La fortezza divenne negli anni seguenti l'estremità orientale della linea fortificata russa da Azov a Mozdok ed è considerata una delle cause della guerra del 1768-74.", "deaad34c"]},
"OLAYLAR_P0068:1789-10-13:0":{"b": ["Belgrado e Smederevo cadono in mano austriaca", "cf874516"], "d": ["Nel terzo anno di guerra il comandante austriaco Loudon prese le fortezze di confine ottomane lungo il Danubio. Smederevo si arrese il 13 ottobre 1789, a condizione che i 300 soldati della guarnigione si ritirassero deponendo le armi; anche Belgrado, fortezza di confine ottomana da cinquant'anni, cadde in mano austriaca nello stesso autunno. Loudon nel 1789-1791 fece costruire trincee che dominavano la rocca e il sobborgo di Smederevo. Entrambe le città furono restituite all'Impero ottomano con il Trattato di Sistova firmato il 4 agosto 1791; per questo sulla mappa sono mostrate come occupazione e non come annessione. Il giorno della resa di Belgrado non compare in nessuna delle quattro voci TDV lette (le voci danno solo l'anno); la data qui è quella di Smederevo e per Belgrado non è una stima, ma l'unico giorno noto della stessa operazione.", "3ab6a49a"]},
"OLAYLAR_P0068:1861-06-13:0":{"b": ["I Circassi si riuniscono a Soči e chiedono aiuto all'Impero ottomano, all'Inghilterra e alla Francia", "d7ae7762"], "d": ["I Circassi, che continuavano a combattere i Russi anche dopo la resa dello sceicco Şâmil (1859), si riunirono a Soči il 13 giugno 1861 e chiesero aiuto all'Impero ottomano, all'Inghilterra e alla Francia. L'aiuto non venne; nello stesso anno, con l'approvazione dello zar, l'espulsione dei Circassi fu ufficialmente decisa e nel 1861-1864 furono occupati i territori di Abzakh, Shapsug e Ubykh. Fu comunicato alla popolazione che entro un mese dovesse stanziarsi nei luoghi indicati lungo il Kuban o emigrare nei territori ottomani, altrimenti sarebbe stata deportata nell'interno della Russia come prigioniera di guerra.", "78005fcf"]},
"OLAYLAR_P0068B:1788-01-25:0":{"b": ["Destituzione di Melek Mehmed Pascià dal visirato — epurazione dei fautori della pace", "a07e5755"], "d": ["Mentre stava per aprirsi il secondo fronte della guerra, Melek Mehmed Pascià fu destituito dal visirato il 25 gennaio 1788. Secondo il TDV la vera ragione della destituzione era che il gran visir Koca Yûsuf Pascià voleva allontanare dal governo i fautori della pace. Melek Mehmed Pascià sarebbe stato nominato gran visir al posto di Koca Yûsuf Pascià alla fine della guerra, il 4 maggio 1792.", "f725e76a"]},
"OLAYLAR_P0068B:1788-02-22:0":{"b": ["Il serdâr-ı ekrem Koca Yûsuf Pascià parte in campagna con pieni poteri", "c16ecddb"], "d": ["Nei giorni in cui si apriva la guerra su due fronti, il gran visir e serdâr-ı ekrem Koca Yûsuf Pascià il 22 febbraio 1788 partì da Costantinopoli alla testa dell'esercito. Abdülhamid I gli diede, nell'espressione del TDV, un'ampia indipendenza al livello dei Köprülü, cioè pieni poteri. Così la condotta e l'amministrazione della guerra furono lasciate interamente nelle mani del serdâr.", "64341325"]},
"OLAYLAR_P0068B:1788-05-10:0":{"b": ["Cezayirli Gazi Hasan Pascià salpa con la flotta nel Mar Nero", "4dc6574c"], "d": ["Il kaptanıderyâ Cezayirli Gazi Hasan Pascià il 10 maggio 1788 salpò con la flotta nel Mar Nero. L'obiettivo era esercitare pressione sulla linea Özi-Kılburun e spezzare la superiorità della flotta russa nel nord del Mar Nero; questa operazione fu l'inizio degli scontri navali che durarono per tutta l'estate.", "9bc90d70"]},
"OLAYLAR_P0068B:1788-08-01:0":{"b": ["Battaglia navale dell'Isola dei Serpenti (Fidonisi)", "5c6a90c1"], "d": ["Cezayirli Gazi Hasan Pascià sconfisse la flotta russa nella battaglia dell'Isola dei Serpenti dell'agosto 1788. Ma questo successo non bastò a salvare le fortezze nel nord del Mar Nero; alla fine dello stesso anno cadde Özi.", "c850a910"]},
"OLAYLAR_P0068B:1789-01-01:0":{"b": ["Akkerman presa dai Russi", "48638c7c"], "d": ["Akkerman fu assediata e presa dai Russi nel 1789; secondo il TDV la fortezza passava in mano russa per la seconda volta dopo il 1770. Tayfur Pascià, che aveva consegnato la fortezza senza combattere, fu fatto giustiziare dal gran visir Cezayirli Gazi Hasan Pascià.", "3e4f5789"]},
"OLAYLAR_P0068B:1789-05-01:0":{"b": ["Disfatta di Galați", "65e7a29d"], "d": ["Le forze ottomane subirono una sconfitta a Galați il 1° maggio 1789. Questa disfatta fu il primo anello di una serie di sconfitte che si sarebbero ripetute per tutta l'estate a Focșani e a Rîmnic, e scosse la posizione del serdâr-ı ekrem Koca Yûsuf Pascià.", "28e100e0"]},
"OLAYLAR_P0068B:1789-06-07:0":{"b": ["Destituzione di Koca Yûsuf Pascià dal gran visirato", "54fdaa33"], "d": ["La disfatta di Galați fu la causa visibile della rimozione di Koca Yûsuf Pascià dal gran visirato il 7 giugno 1789. Al suo posto fu nominato Kethüdâ Hasan Pascià, noto per i suoi successi sul fronte austriaco. Nei tre anni di guerra rimanenti il gran visirato cambiò di mano quattro volte.", "73d2aab3"]},
"OLAYLAR_P0068B:1789-08-01:0":{"b": ["Disfatta di Focșani", "09430751"], "d": ["L'esercito ottomano il 1° agosto 1789 subì a Focșani una grave sconfitta di fronte alle forze russo-austriache. Due voci distinte del TDV danno questo giorno allo stesso modo. La disfatta si sarebbe ripetuta nel settembre dello stesso anno a Rîmnic e la difesa ottomana in Valacchia sarebbe crollata.", "a0cb033c"]},
"OLAYLAR_P0068B:1789-09-22:0":{"b": ["Disfatta di Rîmnic (Boze)", "343edd1a"], "d": ["L'esercito ottomano il 22 settembre 1789 subì una grave disfatta mentre attraversava il fiume Rîmnic e poi sulle rive del Boza. Questa seconda sconfitta, giunta sette settimane dopo Focșani, disperse di fatto il fronte di Valacchia e portò, in ottobre-novembre, alla resa delle fortezze sulla linea del Dnestr: la voce TDV Koca Yûsuf Pascià dà la resa di Ismail l'11 ottobre e quella di Bender il 14 novembre. Tuttavia la resa di Ismail nel 1789 non compare nella voce TDV ismail (nel 1790 la fortezza è ancora in mano ottomana), ESBE scrive che dopo Rîmnic furono prese solo Hacıbey e Akkerman e che Bender si arrese il 3 novembre (calendario giuliano; = 14 novembre); anche TDV akkirman registra che la fortezza fu presa nel 1789 dai Russi. La resa dell'11 ottobre è con ogni probabilità Akkerman — poiché il giorno per Akkerman non può essere verificato nella fonte letta, sulla mappa non è mostrato a parte.", "45226358"]},
"OLAYLAR_P0068B:1789-12-03:0":{"b": ["Nomina di Cezayirli Gazi Hasan Pascià a gran visir e serdâr-ı ekrem", "37e10738"], "d": ["Dopo le disfatte in Valacchia e le perdite di fortezze, il vecchio comandante della flotta Cezayirli Gazi Hasan Pascià fu nominato il 3 dicembre 1789 gran visir e serdâr-ı ekrem. Tre voci distinte del TDV danno questo giorno allo stesso modo. Il suo gran visirato sarebbe durato meno di quattro mesi.", "17c7e52e"]},
"OLAYLAR_P0068B:1790-01-01:0":{"b": ["Sbarco a Calafat e suo respingimento", "f8bc2f38"], "d": ["Le forze ottomane che alla fine dell'aprile 1790 mossero da Vidin e sbarcarono a Calafat attraverso il Danubio furono rapidamente respinte. Questo sbarco fallito coincide con i mesi in cui sul fronte austriaco l'iniziativa passò dalla parte ottomana e iniziò la ricerca di un armistizio.", "09b57c17"]},
"OLAYLAR_P0068B:1790-03-30:0":{"b": ["Morte del serdâr-ı ekrem nell'accampamento di Şumnu — fine di un gran visirato di quattro mesi", "ce61597b"], "d": ["Il gran visir e serdâr-ı ekrem Cezayirli Gazi Hasan Pascià, ultraottantenne, morì il 30 marzo 1790 nell'accampamento di Şumnu. Il suo gran visirato, di tre mesi e ventotto giorni, era coinciso con l'inverno più stretto della guerra.", "7ff18e9d"]},
"OLAYLAR_P0068B:1790-04-16:0":{"b": ["Caduta di Eski Hırsova — fine di un assedio durato tutto l'inverno", "133fe352"], "d": ["Dopo un duro assedio durato tutto l'inverno, Eski Hırsova cadde in mano alle forze austriache il 16 aprile 1790. Negli stessi giorni fu respinto anche lo sbarco compiuto dalla parte ottomana da Vidin a Kalafat attraversando il Danubio.", "1dcb3252"]},
"OLAYLAR_P0068B:1790-06-08:0":{"b": ["Le forze austriache scendono a Giurgiu e sono respinte", "6fbd373f"], "d": ["Le forze austriache l'8 giugno 1790 scesero lungo il Danubio fino a Giurgiu, ma furono respinte dai soldati ottomani. Tre mesi dopo, nello stesso luogo, nella tenda del gran visir, sarebbe stato firmato l'armistizio con l'Austria.", "63725445"]},
"OLAYLAR_P0068B:1790-09-06:0":{"b": ["Decisione di armistizio del consiglio consultivo di Costantinopoli — rinuncia alle condizioni preliminari", "8cb6a44f"], "d": ["Il consiglio consultivo riunito a Costantinopoli il 6 settembre 1790 rinunciò alle condizioni preliminari avanzate per i colloqui con l'Austria. Questa decisione aprì la strada all'armistizio che sarebbe stato firmato dodici giorni dopo a Giurgiu e fece cessare di fatto la guerra sul fronte austriaco.", "f73026d8"]},
"OLAYLAR_P0068B:1790-09-19:0":{"b": ["Armistizio di Giurgiu — tacciono le armi sul fronte austriaco", "87915031"], "d": ["L'armistizio tra l'Impero ottomano e l'Austria fu firmato il 19 settembre 1790 nella tenda del gran visir a Giurgiu. L'armistizio, destinato a restare in vigore nove mesi, fermò i combattimenti sul fronte austriaco, durati due anni e mezzo, e aprì la strada alla conferenza di pace di Sistova.", "919d2742"]},
"OLAYLAR_P0068B:1790-09-21:0":{"b": ["Firma dell'armistizio di Giurgiu da parte di Coburgo e scambio dei testi", "56ce0fee"], "d": ["Il testo dell'armistizio fu firmato il 21 settembre 1790 anche dal comandante in capo austriaco, il principe di Coburgo, e le copie furono consegnate reciprocamente. L'armistizio entrò così in vigore per entrambe le parti.", "a6f60a94"]},
"OLAYLAR_P0068B:1790-12-30:0":{"b": ["Apertura della conferenza di pace di Sistova", "ce5058cb"], "d": ["I delegati ottomani e austriaci si incontrarono per la prima volta a Sistova il 30 dicembre 1790 e si presentarono reciprocamente le credenziali. Iniziarono così trattative che sarebbero durate otto mesi e a un certo punto sarebbero state del tutto interrotte.", "407808c4"]},
"OLAYLAR_P0068B:1791-01-01:0":{"b": ["Assedio russo di Brăila — la fortezza non fu presa", "a5d5844b"], "d": ["La fortezza di Brăila fu assediata dai Russi nel giugno 1791 ma non fu presa. Dopo la disfatta di Măcin nella stessa estate le parti si sarebbero sedute all'armistizio e Brăila sarebbe rimasta in mano ottomana.", "367079fa"]},
"OLAYLAR_P0068B:1791-02-27:0":{"b": ["Secondo gran visirato di Koca Yûsuf Pascià — assunzione dell'incarico nell'accampamento di Şumnu", "c6e04dc4"], "d": ["Dopo il breve gran visirato di Şerif Hasan Pascià, conclusosi con l'esecuzione, il sigillo fu dato di nuovo a Koca Yûsuf Pascià; il pascià il 27 febbraio 1791 si recò all'accampamento di Şumnu e assunse l'incarico. Le trattative per l'armistizio e la pace che avrebbero posto fine alla guerra furono condotte durante il suo secondo gran visirato.", "3331c22b"]},
"OLAYLAR_P0068B:1791-06-10:0":{"b": ["Interruzione dei colloqui di Sistova — la delegazione austriaca si ritira a Bucarest", "b5a0a875"], "d": ["Il plenipotenziario austriaco Herbert il 10 giugno 1791 si ritirò a Bucarest causando l'interruzione dei colloqui; il giorno dopo scadde anche il periodo dell'armistizio. Questa rottura durò cinque settimane e la pace fu salvata solo con l'intervento di Inghilterra e Prussia.", "19ee29e9"]},
"OLAYLAR_P0068B:1791-06-11:0":{"b": ["Fine dell'armistizio di Giurgiu — la pace stretta nella stessa estate", "73e4f9c0"], "d": ["L'armistizio di Giurgiu di nove mesi terminò l'11 giugno 1791. Poiché le trattative in corso a Sistova non erano concluse fino a quel giorno, la pace fu stretta tra la fine dell'armistizio e la possibilità di una ripresa della guerra; il trattato poté essere firmato solo il 4 agosto 1791.", "c0082fb0"]},
"OLAYLAR_P0068B:1791-07-09:0":{"b": ["Disfatta di Măcin — la sconfitta che portò la pace", "ccadcd46"], "d": ["L'esercito ottomano subì a Măcin una disfatta generale e vi fu grande sbandamento. Questa sconfitta, giunta quando l'armistizio con l'Austria era già stato firmato da tempo, rese inevitabile la decisione di sedersi al tavolo anche con la Russia: un mese dopo a Galați fu firmato l'armistizio.", "842dcfca"]},
"OLAYLAR_P0068B:1791-07-18:0":{"b": ["Ripresa dei negoziati di pace — ritorno di Herbert a Sistova", "3715b815"], "d": ["Dopo l'interruzione di cinque settimane la delegazione austriaca tornò a Sistova il 18 luglio 1791. Diciassette giorni dopo, il 4 agosto 1791, sarebbe stato firmato il trattato di pace.", "3f3ed300"]},
"OLAYLAR_P0068B:1791-08-08:0":{"b": ["Intesa sull'armistizio a Galați tra Vâsıf Efendi e il principe Repnin", "f792ca6b"], "d": ["Un mese dopo la disfatta di Măcin, l'8 agosto 1791 a Galați Ahmed Vâsıf Efendi e il comandante russo principe Repnin raggiunsero un'intesa sui fondamenti dell'armistizio. Tre giorni dopo sarebbero stati firmati i documenti dell'armistizio.", "610110f6"]},
"OLAYLAR_P0068B:1791-08-11:0":{"b": ["Armistizio di Galați — tregua di otto mesi con la Russia", "169ee7ec"], "d": ["L'armistizio di otto mesi tra l'Impero ottomano e la Russia fu firmato l'11 agosto 1791; i documenti furono ratificati lo stesso giorno con il titolo di «articoli fondamentali e armistizio». Cessarono così i combattimenti sul fronte russo, durati quattro anni, e fu posto il quadro della pace che sarebbe stata firmata cinque mesi dopo a Iași.", "6b7fb0e3"]},
"OLAYLAR_P0068B:1791-08-12:0":{"b": ["Ratifica del Trattato di Sistova da parte del sultano", "8cbbdccd"], "d": ["Il Trattato di Sistova, firmato il 4 agosto 1791, fu ratificato il 12 agosto. La ratifica cadde il giorno dopo la firma dell'armistizio con la Russia: l'Impero ottomano nella stessa settimana pose fine giuridicamente ai combattimenti su entrambi i fronti.", "4972648f"]},
"OLAYLAR_P0068B:1791-08-31:0":{"b": ["Scambio solenne delle ratifiche di Sistova", "f8419068"], "d": ["Le ratifiche della pace con l'Austria furono scambiate solennemente il 31 agosto 1791; dopo di che il gran visir partì per le trattative di pace sul fronte russo. Il fronte austriaco, aperto nel 1788, fu così chiuso interamente.", "c0ddbdf0"]},
"OLAYLAR_P0068B:1791-10-16:0":{"b": ["Morte di Potëmkin — i colloqui di Iași cambiano di mano dalla parte russa", "78f41463"], "d": ["Il plenipotenziario russo Potëmkin morì il 16 ottobre 1791 lungo la strada mentre andava al Monastero di Nikolaševt. Al suo posto condusse i colloqui il conte Bezborodko; le trattative di pace poterono iniziare regolarmente solo dopo il suo arrivo, in novembre.", "ca581195"]},
"OLAYLAR_P0068B:1791-11-10:0":{"b": ["Inizio dei negoziati ottomano-russi a Iași", "455205f8"], "d": ["Le delegazioni ottomana e russa tennero la prima seduta a Iași il 10 novembre 1791. Per due mesi si sarebbero tenuti sedici incontri, nei quali furono risolte le questioni dell'indennità e dei confini.", "e092f125"]},
"OLAYLAR_P0068B:1792-01-07:0":{"b": ["Quattordicesima seduta a Iași — la Russia rinuncia alla richiesta di indennità", "36aa4c91"], "d": ["Nel quattordicesimo incontro del 7 gennaio 1792 il plenipotenziario russo Bezborodko rinunciò alla richiesta di indennità e dichiarò conclusa la pace. Fu deciso di firmare il testo del trattato tre giorni dopo.", "76f6232b"]},
"OLAYLAR_P0068B:1792-01-18:0":{"b": ["Ratifica del Trattato di Iași con atto del gran visir", "b2f4cec8"], "d": ["Il Trattato di Iași, firmato il 10 gennaio 1792, fu ratificato il 18 gennaio con l'atto rilasciato dal gran visir. La ratifica sarebbe stata seguita da scambi di teyidnâme e tasdiknâme, e la pace sarebbe diventata giuridicamente definitiva all'inizio di febbraio.", "be4cae64"]},
"OLAYLAR_P0068B:1792-01-27:0":{"b": ["Sedicesima seduta a Iași — scambio dei teyidnâme", "26061259"], "d": ["Nel sedicesimo e ultimo incontro, il 27 gennaio 1792, i teyidnâme furono scambiati reciprocamente. La conferenza si chiuse così; restava solo lo scambio delle ratifiche (tasdiknâme) dei sovrani.", "6726568b"]},
"OLAYLAR_P0068B:1792-02-10:0":{"b": ["Scambio delle ratifiche di Iași — la pace diventa definitiva nel diritto internazionale", "7b59d6b3"], "d": ["Le ratifiche dei sovrani furono scambiate il 10 febbraio 1792 e la pace acquistò validità definitiva anche sotto il profilo del diritto internazionale. La guerra su due fronti, durata cinque anni, fu così ufficialmente chiusa; la perdita della Crimea divenne definitiva e il nuovo confine dell'Impero ottomano fu il Turla (Dnestr).", "f0615309"]},
"OLAYLAR_P0068B:1792-05-03:0":{"b": ["Destituzione di Koca Yûsuf Pascià e nomina a governatore di Trebisonda", "ee79414b"], "d": ["Tre mesi dopo che la pace era divenuta definitiva, Selim III il 3 maggio 1792 destituì Koca Yûsuf Pascià, due volte gran visir dall'inizio della guerra, e lo nominò lo stesso giorno governatore di Trebisonda e custode di Anapa. Il gruppo che aveva condotto la guerra fu così rimosso dall'incarico.", "1ff948fd"]},
"OLAYLAR_P0068B:1792-05-04:0":{"b": ["Nomina di Melek Mehmed Pascià a gran visir — costituzione del gruppo riformatore", "bbb92fd7"], "d": ["Melek Mehmed Pascià, rimosso dal visirato nel 1788 perché favorevole alla pace, il 4 maggio 1792 fu nominato gran visir. Con il suo arrivo nella capitale il 7 giugno iniziò la raccolta, presso i dignitari dello Stato, dei progetti sull'ordinamento dello Stato (nizâm-ı devlet); la preparazione del programma del Nizâm-ı Cedîd fu condotta con questo gruppo.", "94e90cff"]},
"OLAYLAR_P0917DUNYA:1915-02-23:0":{"b": ["Occupazione russa di Hopa", "d4bd9ae3"], "d": ["Hopa, rimasta dopo il Trattato di Berlino del 1878 come kaza ottomano nel sancak del Lazistan, fu occupata nella prima guerra mondiale dalle truppe russe; l'occupazione durò fino al 14 marzo 1918.", "4cbc2764"]},
"OLAYLAR_P0917DUNYA:1915-09-26:0":{"b": ["Occupazione britannica di Kut al-Amara", "2447347a"], "d": ["Il generale britannico Townshend, che mirava a prendere Baghdad, si mosse lungo il Tigri e occupò Kut al-Amara, che si trovava sul percorso. La città tornò in mano alle forze turche dopo il protocollo di resa firmato il 29 aprile 1916.", "f815cd30"]},
"OLAYLAR_P0917DUNYA:1916-02-16:0":{"b": ["Caduta di Erzurum sotto occupazione russa", "4bcf972b"], "d": ["Le forze russe, che dall'inizio della guerra avevano scelto Erzurum come obiettivo principale, entrarono in città; Erzurum subì per la terza volta l'occupazione russa. L'occupazione durò fino al 12 marzo 1918.", "65611111"]},
"OLAYLAR_P0917DUNYA:1916-02-24:0":{"b": ["Occupazione russa di Aşkale", "c0b4232f"], "d": ["Le forze russe, che avevano preso Erzurum il 16 febbraio 1916, avanzando verso ovest occuparono Aşkale il 24 febbraio. Aşkale fu liberata il 3 marzo 1918.", "6b05668a"]},
"OLAYLAR_P0917DUNYA:1916-03-01:0":{"b": ["Occupazione russa di Bitlis", "2cdb1cbc"], "d": ["Le forze russe occuparono Bitlis. L'occupazione durò fino all'8 agosto 1916.", "b311d03c"]},
"OLAYLAR_P0917DUNYA:1916-03-08:0":{"b": ["Occupazione russa di Rize: caduta della costa del Mar Nero orientale", "263f36d3"], "d": ["Le truppe russe, passate all'attacco il 7 febbraio 1916 da Batum in direzione di Arhavi, avanzando verso ovest lungo la costa occuparono Pazar il 4 marzo, Çayeli il 5 marzo, Rize l'8 marzo e Of il 26 marzo. Trebisonda fu presa per via di terra alla fine di questa avanzata, il 18 aprile 1916.", "5edb2835"]},
"OLAYLAR_P0917DUNYA:1916-04-18:0":{"b": ["Occupazione russa di Trebisonda", "5d166ea1"], "d": ["Le truppe russe, che il 14 aprile avevano sfondato la linea difensiva di Karadere e il 16 aprile erano giunte a Yomra, entrarono a Trebisonda il 18 aprile dopo che la popolazione turca aveva evacuato la città. L'occupazione russa durò fino al 24 febbraio 1918.", "311840b1"]},
"OLAYLAR_P0917DUNYA:1916-07-16:0":{"b": ["Occupazione russa di Bayburt e Gümüşhane", "a4229eff"], "d": ["Con lo sfondamento della difesa di Kop le truppe russe occuparono Bayburt il 16 luglio 1916, Gümüşhane il 19 luglio e Kelkit il 22 luglio; Erzincan cadde dopo di esse, il 24 luglio.", "04312d2b"]},
"OLAYLAR_P0917DUNYA:1916-07-24:0":{"b": ["Occupazione russa di Erzincan", "81c11c05"], "d": ["Le forze russe occuparono Erzincan il 24 luglio 1916. La città fu liberata il 26 febbraio 1918.", "964bb144"]},
"OLAYLAR_P0917DUNYA:1916-08-08:0":{"b": ["Bitlis liberata dall'occupazione russa", "8294f009"], "d": ["L'occupazione russa iniziata il 1° marzo 1916 finì con il ritiro dei Russi dalla città.", "d172c696"]},
"OLAYLAR_P0917DUNYA:1916-09-17:0":{"b": ["Taif passa alle forze dello Sharif Hussein", "3924f74f"], "d": ["Durante la prima guerra mondiale le forze dello Sharif Hussein, sollevatosi contro il dominio ottomano e sostenuto dagli Inglesi, presero Taif. Durante l'assedio la città subì gravi danni.", "77eb751d"]},
"OLAYLAR_P0917DUNYA:1916-11-06:0":{"b": ["Uccisione di Ali Dinar — finisce il Sultanato del Darfur, il Darfur unito al Sudan britannico", "17796ae7"], "d": ["Ali Dinar, sultano del Darfur, che durante la prima guerra mondiale si era avvicinato all'Impero ottomano, dopo la caduta della capitale El Fasher nel maggio 1916 si era ritirato verso il Gebel Marra; fu ucciso il 6 novembre 1916 da forze inviate dal governo del Sudan. Qualche tempo dopo il territorio del Darfur fu unito come provincia al Sudan britannico.", "77fea96b"]},
"OLAYLAR_P0917DUNYA:1917-03-07:0":{"b": ["Occupazione britannica di Najaf", "eff495f9"], "d": ["Najaf, centro di kaza dipendente dal sancak di Kerbela nel vilayet di Baghdad negli ultimi tempi ottomani, fu occupata dagli Inglesi il 7 marzo 1917; quattro giorni dopo cadde anche Baghdad. La città fu inclusa nei confini dell'Iraq con la monarchia fondata nel 1920.", "737a90d9"]},
"OLAYLAR_P0917DUNYA:1917-12-06:0":{"b": ["Khanaqin entra nella linea britannica", "daef063a"], "d": ["Dopo l'operazione di Hamrin il III Corpo britannico il 6 dicembre 1917 si attestò sulla linea avanzata da Khanaqin a Kızılrubat; Khanaqin restò in seguito in mano britannica e divenne la testa della via per la Persia.", "968eb7b5"]},
"OLAYLAR_P0917DUNYA:1918-02-19:0":{"b": ["Liberazione di Bayburt e Gümüşhane", "15162c86"], "d": ["Nell'avanzata iniziata con la denuncia dell'Armistizio di Erzincan, Kelkit fu liberata il 17 febbraio e Bayburt il 19 febbraio; l'occupazione russa a Gümüşhane terminò il 28 febbraio 1918.", "6ac1cb20"]},
"OLAYLAR_P0917DUNYA:1918-02-24:0":{"b": ["Liberazione di Trebisonda dall'occupazione russa", "d0c44c85"], "d": ["I Russi si ritirarono da Trebisonda e l'occupazione, durata circa due anni, finì.", "7a57114d"]},
"OLAYLAR_P0917DUNYA:1918-02-26:0":{"b": ["Liberazione di Erzincan", "2700373c"], "d": ["Erzincan, sotto occupazione russa dal 24 luglio 1916, fu liberata dalle truppe turche.", "d3617b82"]},
"OLAYLAR_P0917DUNYA:1918-03-02:0":{"b": ["Liberazione di Rize: riconquista della costa del Mar Nero orientale", "cab60e94"], "d": ["Con il ritiro dei Russi le truppe turche avanzarono verso est lungo la costa: Rize il 2 marzo, Çayeli il 9 marzo e Hopa il 14 marzo 1918 tornarono sotto l'amministrazione ottomana.", "014dea28"]},
"OLAYLAR_P0917DUNYA:1918-03-12:0":{"b": ["Liberazione di Erzurum", "6c832f86"], "d": ["Le truppe turche al comando di Kâzım Karabekir Pascià liberarono Erzurum dalle unità armene; la città, dopo due anni di occupazione, tornò sotto l'amministrazione ottomana.", "43ae103d"]},
"OLAYLAR_P0917DUNYA:1918-04-01:0":{"b": ["Disfatta di Tuz Hurmatu — le truppe ottomane si ritirano a Kirkuk", "d844b61f"], "d": ["Verso la fine della prima guerra mondiale, nell'aprile 1918 le truppe ottomane, sconfitte dalle forze britanniche a Tuz Hurmatu, si ritirarono a Kirkuk; la cittadina passò sotto occupazione britannica.", "07529ee4"]},
"OLAYLAR_P0917DUNYA:1918-04-28:0":{"b": ["Operazione nel Kurdistan meridionale: la colonna C entra a Kifri", "13b40542"], "d": ["Nell'operazione nel Kurdistan meridionale la colonna C britannica entrò a Kifri la mattina del 28 aprile 1918 senza incontrare resistenza. Quando alla fine di maggio Kirkuk fu abbandonata, Kifri e Tuz Hurmatu furono comunque tenute come avamposti britannici.", "bcae14d1"]},
"OLAYLAR_P0917DUNYA:1918-05-07:0":{"b": ["Occupazione britannica di Kirkuk", "6f7a899f"], "d": ["Le truppe ottomane, sconfitte a Tuz Hurmatu nell'aprile 1918, si ritirarono a Kirkuk; il 7 maggio gli Inglesi occuparono Kirkuk.", "dd627ad7"]},
"OLAYLAR_P0917DUNYA:1918-05-27:0":{"b": ["Riconquista di Kirkuk", "9e911edf"], "d": ["Dopo venti giorni di occupazione britannica Kirkuk fu ripresa dalle forze ottomane il 27 maggio 1918. La città passò di nuovo all'amministrazione britannica quando, con le offensive britanniche iniziate il 28 ottobre 1918, le truppe ottomane si ritirarono ad Altınköprü.", "08a1b3e0"]},
"OLAYLAR_P0917DUNYA:1918-07-12:0":{"b": ["Capolinea della ferrovia di Samarra: un distaccamento britannico si stabilisce a Tikrit", "7015ab60"], "d": ["Dopo la battaglia di Tikrit del 5 novembre 1917 le forze britanniche si erano ritirate il 10 novembre a Samarra. Il 12 luglio 1918 un distaccamento del I Corpo occupò Tikrit per proteggere il prolungamento della ferrovia di Samarra.", "baff356d"]},
"OLAYLAR_P0917DUNYA:1918-09-15:0":{"b": ["L'Esercito islamico del Caucaso prende Baku", "1ac40958"], "d": ["L'Esercito islamico del Caucaso al comando di Nuri Pascià, giunto in aiuto della Repubblica Democratica dell'Azerbaigian in base al Trattato di Batum del 4 giugno 1918, prese Baku, in mano ai Russi. Dopo l'Armistizio di Mudros le forze ottomane si ritirarono dalla città; la repubblica finì il 27 aprile 1920 con l'occupazione dell'Armata Rossa.", "31413075"]},
"OLAYLAR_P0917DUNYA:1921-02-25:0":{"b": ["Ingresso dell'Armata Rossa a Tbilisi: caduta della Repubblica Democratica di Georgia", "de0e19cd"], "d": ["La Georgia, che aveva proclamato l'indipendenza il 26 maggio 1918, fu occupata dalla Russia sovietica nel febbraio 1921; il 25 febbraio 1921 i bolscevichi entrarono a Tbilisi e instaurarono il regime sovietico. Con questo evento Gori, Telavi e Dušeti (Georgia orientale) passarono sotto il controllo della Russia sovietica.", "ea05a868"]},
"OLAYLAR_P0917KOSU13:1387-01-01:0":{"b": ["Conquista di Vodina (inverno 1386-1387)", "1e542d14"], "d": ["Vodina, in Macedonia a ovest del Vardar, entrò sotto l'amministrazione ottomana con una conquista per la quale le cronache ottomane danno anni diversi. Hoca Sâdeddin pone la conquista al 1386; il TDV ritiene più appropriato, con forte probabilità, accettare l'inverno 1386-1387. Poiché il comandante che compì la conquista non è citato esplicitamente nella fonte, non è stato scritto alcun nome.", "0da93b6a"]},
"OLAYLAR_P0917KOSU13:1415-01-01:0":{"b": ["Manisa passa sotto il governo di Çelebi Mehmed — fine del ramo di Manisa dei Saruhanoğulları", "6d6c7622"], "d": ["Alla fine dell'Interregno ottomano il paese di Saruhan passò sotto il governo di Çelebi Mehmed e il ramo di Manisa dei Saruhanoğulları scomparve dalla storia. Il TDV pone questo passaggio dopo il 1411 e prima del 1415; il governo ottomano poté essere stabilito pienamente poco prima dell'818 (1415). La data è quindi scritta con l'estremo più tardo dell'intervallo.", "4d3e8c85"]},
"OLAYLAR_P0917KOSU13:1427-01-01:0":{"b": ["Giurgiu passa alla Valacchia", "bc5c11f4"], "d": ["La fortezza di Giurgiu (Yergöğü) sul Danubio fu ripresa dai Valacchi nel 1427. La fortezza era uno dei primi punti d'appoggio ottomani sulla riva settentrionale del Danubio e rimase alla Valacchia per oltre vent'anni.", "91dc683d"]},
"OLAYLAR_P0917KOSU13:1450-01-01:0":{"b": ["Giurgiu torna sotto controllo ottomano (853/1449-50)", "c9ad1b89"], "d": ["La fortezza di Giurgiu, ripresa dai Valacchi nel 1427, tornò sotto controllo ottomano nell'anno 853. Poiché l'anno egirino si estende dal febbraio 1449 al febbraio 1450, la data è scritta con l'inizio dell'anno 1450, compreso nell'intervallo. La fortezza divenne da allora un confine ottomano a protezione del passaggio del Danubio.", "15b80685"]},
"OLAYLAR_P0917KOSU13:1516-10-01:0":{"b": ["Gerusalemme e le città della Palestina passano sotto il governo ottomano", "7ac58e9d"], "d": ["Dopo la vittoria di Marj Dabiq, con l'arrivo di Selim I il Severo a Damasco il 27 settembre le città di Siria e Palestina passarono una dopo l'altra sotto il governo ottomano. Il TDV indica che Nablus entrò sotto il governo ottomano nell'autunno 1516, e Gerusalemme probabilmente nell'ottobre 1516, prima dell'arrivo del sultano. Il sultano giunse a Gerusalemme soltanto dopo la battaglia di Gaza, il 29 dicembre 1516.", "7680d172"]},
"OLAYLAR_P0917KOSU13:1532-01-01:0":{"b": ["Bitlis passa sotto protezione safavide — Ulama e Fil Pascià tolgono l'assedio", "2d0610f6"], "d": ["Poiché Tekelü Ulama si era rifugiato presso gli Ottomani ed era stato nominato beylerbey sul territorio di Bitlis, Şeref Khan, signore di Bitlis e vassallo ottomano, si rifugiò presso i Safavidi. Ulama e il beylerbey di Diyarbekir Fil Pascià assediarono la fortezza nell'anno 938; la fortezza resistette tre mesi e le forze ottomane, venuto a sapere che lo scià Tahmasp si avvicinava, tolsero l'assedio. Lo scià legò a Şeref Khan Bitlis e le zone di Ahlat, Muş e Hınıs.", "8b605ee5"]},
"OLAYLAR_P0917KOSU13:1534-01-01:0":{"b": ["Bitlis definitivamente unita agli Ottomani da Ulama Pascià", "7631002a"], "d": ["Tekelü Ulama, il cui primo assedio era fallito, uccise nel 940 (1533) Şeref Khan, signore di Bitlis, e nel 1534 unì definitivamente Bitlis al territorio ottomano. Şemseddin Bey, figlio di Şeref Khan, dopo che Bitlis fu data a Ulama si rifugiò presso i Safavidi con la tribù dei Rojeki. Il dominio ottomano su Bitlis fu riconosciuto anche dai Safavidi con la Pace di Amasya del 1555.", "3d1f3e99"]},
"OLAYLAR_P0917KOSU13:1565-01-01:0":{"b": ["Presa della fortezza di Krupa da parte degli Ottomani", "7a786bf3"], "d": ["La fortezza di Krupa, sulla riva destra dell'Una, cadde in mano ottomana nel 1565. Nei due secoli seguenti la fortezza restò ottomana nonostante gli assedi austriaci (1581, 1690, 1692, 1716) e fece parte della linea di confine dell'Una tra Bihać e Novi.", "e7a52e35"]},
"OLAYLAR_P0917KOSU13:1578-08-24:0":{"b": ["Presa di Tbilisi senza combattere — sottomissione di Kakheti e Imereti", "b1563ee6"], "d": ["L'esercito ottomano al comando di Lala Mustafa Pascià, che avanzava dopo la vittoria di Çıldır, giunse a Tbilisi il 24 agosto e prese senza combattere la fortezza evacuata. Dopo la conquista di Tbilisi i governanti di Imereti e Kakheti dichiararono la loro obbedienza agli Ottomani.", "41a9cb07"]},
"OLAYLAR_P0917KOSU13:1588-09-01:0":{"b": ["Sottomissione a Cafer Pascià di Şâhverdi Khan, signore di Karacadağ (Ahar) — Marand entra nell'amministrazione ottomana", "fe55fb37"], "d": ["Il beylerbey di Tabriz Cafer Pascià nel 1588 estese il proprio dominio a Marand; Şâhverdi Khan, signore di Karacadağ, si sottomise e mandò il figlio a Tabriz. Le fonti danno solo l'anno; il giorno è abbinato alla campagna di Ganja dello stesso anno.", "9a1a0cee"]},
"OLAYLAR_P0917KOSU13:1589-01-01:0":{"b": ["Cığalazâde Sinan Pascià prende Nihavand e vi costruisce una fortezza — sottomissione del Luristan", "1a6a0329"], "d": ["Il governatore di Baghdad Cığalazâde Sinan Pascià alla fine del 1588 prese Nihavand e vi fece costruire una fortezza; Şâhverdi, signore del Luristan, si sottomise agli Ottomani. Le fonti non danno il giorno; la data è a livello d'anno.", "89a4eefd"]},
"OLAYLAR_P0917KOSU13:1722-11-01:0":{"b": ["Gli Ottomani riconoscono il dominio di Hacı Dâvud sullo Shirvan", "8e7b0476"], "d": ["Nel novembre 1722, mentre davano alle forze russe un ultimatum per ritirarsi dalla regione, gli Ottomani riconobbero il dominio di Hacı Dâvud sullo Shirvan. Hacı Dâvud divenne così un sovrano vassallo legato agli Ottomani, come il khan di Crimea.", "6b466aaf"]},
"OLAYLAR_P0917KOSU13:1723-08-06:0":{"b": ["I Russi prendono Baku", "482170dc"], "d": ["Nel secondo anno della campagna del Caspio di Pietro I il corpo del generale Matjuškin, giunto dal mare, prese Baku. La città rimase sotto guarnigione russa fino a quando fu restituita alla Persia nel 1735 con il Trattato di Ganja. La voce TDV Bakü colloca la restituzione nel 1734; le fonti russe e persiane danno il Trattato di Ganja del 1735.", "29dc4fb3"]},
"OLAYLAR_P0917KOSU13:1723-11-10:0":{"b": ["Consegna di Senendec (Sanandaj), centro dell'Erdelan", "83b23183"], "d": ["Dopo la presa di Kermanshah, Hane Mehmed Pascià, bey dei Baban inviato contro l'Erdelan, ricevette in consegna Senendec, centro della provincia; anche i livâ di Mihribân (Marivan), Bâne e Sakız furono uniti all'eyalet ottomano di Erdelan. Nel 1727 fu redatto per l'eyalet un dettagliato registro di tahrir ottomano.", "e4060148"]},
"OLAYLAR_P0917KOSU13:1724-01-01:0":{"b": ["Urmia e Salmas passano all'amministrazione ottomana", "1e25828f"], "d": ["Negli anni in cui lo Stato safavide si dissolveva con l'invasione afghana, Urmia entrò ancora una volta sotto il dominio ottomano. Nel 1728 fu redatto un registro di tahrir ottomano per Urmia e per il livâ di Salmas ad essa legato. Nell'offensiva di Nâdir del 1729-1730 la regione fu perduta; Hekimoğlu Ali Pascià riprese Urmia nel 1731.", "505c034f"]},
"OLAYLAR_P0917KOSU13:1725-09-09:0":{"b": ["Presa di Ardabil", "917ebe96"], "d": ["Dopo Tabriz le forze di Köprülüzâde Abdullah Pascià entrarono ad Ardabil, centro spirituale dei Safavidi. Nel 1728 la città fu registrata nel tahrir, con i distretti di Serab e Miyane, come livâ ottomano di Ardabil; anche la vicina Khalkhal fu registrata come livâ a parte. Nâdir riprese Ardabil nel 1730.", "1fe99397"]},
"OLAYLAR_P0917KOSU13:1731-11-15:0":{"b": ["Hekimoğlu Ali Pascià riprende Tabriz", "fda463ac"], "d": ["Hekimoğlu Ali Pascià riprese il 15 novembre 1731 Tabriz, passata ai Safavidi nel 1730; nella stessa operazione era stata presa anche Urmia. Ma con il trattato del 10 gennaio 1732 Tabriz fu lasciata alla Persia. L'atlante considera passata in questo giorno dai Safavidi agli Ottomani anche Kotur, che segue la catena di Hoy (TDV hoy; il giorno specifico per Kotur non è nella fonte — approssimazione dichiarata).", "9847bdc5"]},
"OLAYLAR_P0917KOSU13:1735-10-03:0":{"b": ["Consegna di Erevan a Nâdir Khan", "371ef64b"], "d": ["Nâdir Khan, che dopo la disfatta di Arpaçay (Baghavard) aveva preso Ganja il 9 luglio e Tbilisi il 12 agosto, prese anche Erevan. Anche i distretti di Karpi (Üçkilise), Şerür e Makû passarono alla Persia insieme al centro della provincia.", "d2c03da0"]},
"OLAYLAR_P0917KOSU13:1736-03-24:0":{"b": ["La Russia marcia su Azov e sulla Crimea — la guerra ottomano-russa inizia di fatto", "c6d4dbc7"], "d": ["La Russia, che considerava una violazione del proprio territorio il passaggio delle forze di Crimea attraverso la Cabardia diretti al fronte persiano, con questo pretesto marciò senza dichiarare guerra su Azov e sulla Crimea con due colonne. Münnich passò il Don e prese le fortezze davanti ad Azov. Il divan ottomano decise la guerra solo il 2 maggio 1736.", "c7d0e549"]},
"OLAYLAR_P0917KOSU13:1739-12-12:0":{"b": ["Ahidname della pace con la Russia: la Cabardia neutrale, Azov sarà demolita", "27454835"], "d": ["L'ahidname della pace con la Russia fu redatto il 12 dicembre 1739. Le fortificazioni di Azov sarebbero state demolite lasciando tra i due Stati una zona cuscinetto vuota, e la Cabardia non sarebbe appartenuta né alla Russia né agli Ottomani (art. 6). Özi e Kılburun restarono agli Ottomani.", "02e73b3a"]},
"OLAYLAR_P0917KOSU13:1770-09-01:0":{"b": ["Resa della fortezza di Kili a Repnin", "e894b7d0"], "d": ["Dopo la disfatta di Kartal la colonna di Repnin, scesa alla foce del Danubio, giunse davanti a Kili il 10 agosto (calendario giuliano). Dopo il fuoco delle batterie nella breccia e dieci giorni di difesa, i difensori consegnarono la fortezza a condizione di uscire liberamente con le armi e i beni della popolazione. Kili fu restituita agli Ottomani con il Trattato di Küçük Kaynarca (1774).", "fb66a9e9"]},
"OLAYLAR_P0917KOSU13:1770-10-09:0":{"b": ["Cade la fortezza di Akkerman alla foce del Dnestr", "018c420b"], "d": ["Poco dopo la caduta di Bender, anche Akkerman, alla foce del Dnestr, cadde in mano alle forze russe. La fortezza fu restituita agli Ottomani con il Trattato di Küçük Kaynarca (1774).", "38e48332"]},
"OLAYLAR_P0917KOSU13:1788-08-26:0":{"b": ["Caduta di Dubica in mano austriaca", "66d70917"], "d": ["I primi attacchi austriaci della primavera 1788 erano stati respinti. In agosto il maresciallo Laudon riprese l'assedio; la fortezza, esaurite le provviste e le munizioni, si arrese il 26 agosto 1788. Dubica, insieme a Novi, caduta in ottobre, fu l'unico successo militare austriaco di quell'anno. La fortezza fu restituita agli Ottomani con il Trattato di Sistova del 1791.", "658f6f5a"]},
"OLAYLAR_P0917KOSU13:1788-09-01:0":{"b": ["Presa di Hotin da parte delle forze austro-russe", "a6c18567"], "d": ["Nella guerra iniziata nel 1787 le forze congiunte di Austria e Russia assediarono Hotin e la fortezza fu presa da esse nel settembre 1788. Secondo il Trattato di Sistova l'Austria tenne la fortezza in custodia fino alla fine della pace russa; Hotin fu restituita agli Ottomani con il Trattato di Iași del 1792.", "59f8979f"]},
"OLAYLAR_P0917KOSU13:1788-10-03:0":{"b": ["Laudon prende la fortezza di Novi sull'Una", "80651c30"], "d": ["Dopo Dubica Laudon marciò sulla fortezza di Novi sull'Una e la prese il 3 ottobre 1788; il capitano Cerić e tutti i difensori furono fatti prigionieri. Per la perdita delle due fortezze fu proclamata in Bosnia la mobilitazione generale. Novi fu restituita con il Trattato di Sistova del 1791.", "36ddff90"]},
"OLAYLAR_P0917KOSU13:1789-11-01:0":{"b": ["Occupazione di Bucarest da parte dell'esercito austriaco (Coburgo)", "ec890b9a"], "d": ["Dopo la sconfitta di Rîmnic l'esercito austriaco occupò all'inizio del novembre 1789 Bucarest, centro della Valacchia. La città fu restituita alla parte ottomana con il Trattato di Sistova del 4 agosto 1791.", "8c031b96"]},
"OLAYLAR_P0917KOSU13:1789-11-14:0":{"b": ["Resa della fortezza di Bender a Potëmkin", "a661bafa"], "d": ["Nella guerra ottomano-russa del 1787-1792 la fortezza di Bender sul Dnestr si arrese all'esercito russo al comando di Potëmkin. La fortezza fu restituita agli Ottomani con il Trattato di Iași del 1792.", "b150e1c5"]},
"OLAYLAR_P0917KOSU13:1790-10-24:0":{"b": ["Resa della fortezza di Kili ai Russi", "5e88acfe"], "d": ["Nella campagna del 1790 la fortezza di Kili, alla foce del Danubio, fu assediata il 4 ottobre (calendario vecchio) e nove giorni dopo si arrese al generale Gudovič. La fortezza fu restituita agli Ottomani con il Trattato di Iași del 1792.", "45089b90"]},
"OLAYLAR_P0917KOSU13:1809-09-26:0":{"b": ["Resa della fortezza di Ismail al generale Zass", "dc74c6d0"], "d": ["Durante la guerra ottomano-russa del 1806-1812 la fortezza di Ismail sul Danubio si arrese al generale Zass. La fortezza fu lasciata alla Russia con la Bessarabia dal Trattato di Bucarest del 1812.", "4d43c35c"]},
"OLAYLAR_P0917KOSU13:1838-01-01:0":{"b": ["I Russi prendono i porti circassi di Soči e Tuapse", "75679594"], "d": ["Sulla costa dei Circassi, che non riconoscevano il Trattato di Adrianopoli e restavano di fatto indipendenti, i Russi nel 1838 presero i porti di Soči e Tuapse. L'occupazione dell'interno circasso fu completata nel 1861-1864.", "36d3e541"]},
"OLAYLAR_P0917KOSU13:1854-01-01:0":{"b": ["Nella guerra di Crimea i Russi evacuano e fanno saltare in aria la fortezza di Velyaminovskij a Tuapse", "2202f051"], "d": ["Nella guerra di Crimea, con l'ingresso nel Mar Nero della flotta anglo-francese, le fortezze russe sulla costa circassa, divenute indifendibili, furono evacuate; fu abbandonata e fatta saltare in aria anche la fortezza di Velyaminovskij, costruita a Tuapse nel 1838. La costa restò per circa dieci anni di nuovo sotto il controllo delle tribù circasse.", "2b772139"]},
"OLAYLAR_P0917KOSU13:1864-02-01:0":{"b": ["I Russi riprendono l'antica fortezza di Velyaminovskij a Tuapse", "a7ca0939"], "d": ["Nell'ultimo anno della conquista del Caucaso occidentale le truppe russe sbarcarono sulla costa circassa e rioccuparono il sito della fortezza di Velyaminovskij, evacuata dieci anni prima. In pochi mesi la resistenza circassa finì e la popolazione della costa fu in gran parte deportata nei territori ottomani.", "12049c51"]},
"OLAYLAR_P0917TARAF:1886-01-01:0":{"b": ["Accordo franco-ottomano — tracciato il tratto costiero del confine tra Tunisia e Tripolitania", "52a273ad"], "d": ["Cinque anni dopo che la Tunisia era passata sotto protettorato francese nel 1881, la Francia e l'Impero ottomano fissarono il confine tra la Tunisia e il vilayet di Tripolitania per un breve tratto a partire dalla costa mediterranea. La fonte dà solo l'anno; le coordinate della linea non sono note.", "ef857ca6"]},
"OLAYLAR_P0917TARAF:1892-01-01:0":{"b": ["Secondo accordo franco-ottomano — il confine tra Tunisia e Tripolitania esteso fino a Ghadames", "94885487"], "d": ["Un secondo accordo franco-ottomano fissò il confine tra la Tunisia e il vilayet di Tripolitania in modo più dettagliato di prima e, nell'interno, fino a Ghadames. Il documento che tracciò il confine attuale è la Convenzione di Tripoli, che sarebbe stata firmata diciotto anni dopo.", "b9df9291"]},
"OLAYLAR_P0917TARAF:1906-10-01:0":{"b": ["Accordo di Rafah — descritta la linea Rafah-Taba tra l'Impero ottomano e il Khedivato d'Egitto", "f10d25c6"], "d": ["Dopo la crisi di Aqaba-Taba del 1906 i commissari ottomano e khediviale si accordarono a Rafah su una linea di separazione amministrativa; la linea andava da Ras Taba, sul Golfo di Aqaba, al punto medio tra due colonne a Rafah. La commissione mista tra la fine dello stesso anno e il febbraio seguente eresse lungo la linea novantuno colonne in muratura. Questa linea è l'attuale confine tra Egitto e Israele e tra Egitto e Gaza.", "28a925f5"]},
"OLAYLAR_P0917TARAF:1909-04-19:0":{"b": ["Protocollo turco-bulgaro a Costantinopoli — l'Impero ottomano riconosce l'indipendenza della Bulgaria", "97302dc1"], "d": ["Con il protocollo firmato a Costantinopoli per mediazione della Russia, l'Impero ottomano riconobbe ufficialmente l'indipendenza della Bulgaria, proclamata unilateralmente sei mesi prima. Così il vecchio confine ottomano-bulgaro sullo Strandža divenne anche giuridicamente la linea tra due Stati indipendenti; questo tratto fa parte ancora oggi del confine tra Turchia e Bulgaria.", "393405ba"]},
"OLAYLAR_P0917TARAF:1910-05-19:0":{"b": ["Convenzione di Tripoli — tracciato il confine tra Tunisia e vilayet di Tripolitania da Ras Ajdir a Ghadames", "9ca9e95a"], "d": ["La convenzione firmata a Tripoli tra la Francia e l'Impero ottomano descrisse il confine tra la Tunisia e il vilayet di Tripolitania da Ras Ajdir, sulla costa mediterranea, fino a sud di Ghadames. La commissione mista nel 1910-1911 segnò la linea con oltre duecento pietre; la linea è ancora oggi il confine tra Libia e Tunisia. Due anni dopo questo confine passò dagli Ottomani all'Italia con il Trattato di Ouchy.", "74a4bc3f"]},
"OLAYLAR_P0917TARAF:1913-11-17:0":{"b": ["Protocollo di Costantinopoli — delimitazione del confine turco-persiano", "daa100b9"], "d": ["I rappresentanti ottomani e persiani, sotto la supervisione degli ambasciatori britannico e russo, firmarono a Costantinopoli il protocollo di delimitazione del confine turco-persiano, basato sul Trattato di Erzurum del 1847. La commissione mista fino all'ottobre dell'anno seguente segnò la linea sul terreno, tranne un breve tratto attorno a Kotur. Questa linea, rimasta nel 1923 confine turco-iraniano, fu modificata in tre tratti nel 1932 e nel 1937.", "4bb44a7b"]},
"OLAYLAR_P0917TARAF:1915-09-06:0":{"b": ["Convenzione di Sofia — rettifica del confine ottomano-bulgaro", "42026201"], "d": ["La convenzione firmata a Sofia poco prima dell'ingresso in guerra della Bulgaria a fianco degli Ottomani rettificò il confine ottomano-bulgaro tracciato dal Trattato di Costantinopoli del 1913. Il tratto della linea nella Tracia orientale fu segnato di nuovo nel 1921 dalla commissione di Neuilly e confermato a Losanna.", "b259b598"]}
});
